INSERT INTO `prodi` VALUES (1,1,'Manajemen Pemasaran','D3','Baik Sekali','A.Md.M.','Rp 1.600.000','Program Studi D3 Manajemen Pemasaran adalah pendidikan vokasi yang mencetak lulusan siap kerja di bidang bisnis dan penjualan. Di sini, mahasiswa belajar cara mencari peluang pasar, merancang promosi, mengelola penjualan, hingga memanfaatkan media digital untuk pemasaran dengan total 110 SKS.','VISI:\n\"Menjadi program studi vokasi yang unggul dalam bidang pemasaran dan adaptif terhadap perkembangan IPTEK\"\n\nMISI:\n1. Menyelenggarakan pendidikan vokasi untuk menghasilkan lulusan beretika, berjiwa wirausaha, dan berbasis IPTEK yang mampu mengisi pasar kerja lokal, nasional, dan internasional.\n2. Melaksanakan penelitian terapan yang inovatif dalam bidang manajemen pemasaran berbasis IPTEK.\n3. Mengaplikasikan IPTEK dalam bentuk pengabdian kepada masyarakat, industri, dan pemerintah.','Pengantar Bisnis, Manajemen Pemasaran, Manajemen Keuangan, Manajemen Bauran Pemasaran, Manajemen Pemasaran Jasa, Manajemen Logistik dan Distribusi, Pemasaran Internasional, Perilaku Konsumen, Komunikasi Bisnis, Perpajakan, Pemasaran Pariwisata, Manajemen Ritel, Riset Pemasaran, Digital Marketing, Praktikum Kewirausahaan, PKL, Laporan Akhir.','Digital Marketer / Spesialis Pemasaran Digital, Sales & Marketing Executive, Market Researcher / Analis Pasar, Customer Relationship Officer, Brand Specialist / Pengembang Merek, Wirausaha (Entrepreneur).','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan Seleksi Mandiri (SMMPTN UNTAD).','FEKON/Manajemen Pemasaran.png','https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3989.317!2d119.894!3d-0.834!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x0!2zMMKwNTAnMDIuNCJTIDExOcKwNTMnMzguNCJF!5e0!3m2!1sid!2sid!4v1'),(2,11,'Sistem Informasi','S1','Baik','S.Kom.','Rp 3.000.000','Program Studi S1 Sistem Informasi FATEK UNTAD adalah jenjang pendidikan sarjana akademik yang berfokus pada penggabungan ilmu komputer (teknologi) dengan tata kelola manajemen bisnis. Mahasiswa dibekali keahlian mendalam dalam menganalisis kebutuhan sistem, merancang arsitektur basis data, mengembangkan aplikasi bisnis, serta mengelola proyek teknologi informasi untuk meningkatkan efisiensi operasional dan pengambilan keputusan strategis di instansi maupun perusahaan modern.','VISI KEILMUAN:\n\"Program studi berstandar Internasional yang unggul dalam pengembangan ilmu pengetahuan, teknologi dan sistem informasi cerdas yang berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan sistem informasi yang berstandar internasional menghasilkan lulusan yang adaptif terhadap perkembangan teknologi dan sistem informasi cerdas yang berwawasan lingkungan.\n2. Mengembangkan penelitian inovatif dalam bidang teknologi dan sistem informasi cerdas yang berwawasan lingkungan.\n3. Mengimplementasikan solusi berbasis teknologi dan sistem informasi cerdas yang berwawasan lingkungan untuk meningkatkan kualitas hidup masyarakat.\n4. Mengembangkan kerja sama strategis dengan dunia usaha, industri, serta institusi nasional dan internasional di bidang sistem informasi.','Algoritma & Pemrograman, Struktur Data, Basis Data, Rekayasa Perangkat Lunak, Analisis & Perancangan Sistem Informasi, Manajemen Proyek TI, Pemrograman Berorientasi Objek, Pemrograman Web & Mobile, Sistem Informasi Enterprise, Tata Kelola TI, Kecerdasan Bisnis.','System Analyst (Analis Sistem), Database Administrator, IT Project Manager, Business Analyst, Data Scientist / Data Analyst, Tech Entrepreneur / Startup Founder.','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.','FATEK/JTI/SI.png','https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3989.317!2d119.894!3d-0.834!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x0!2zMMKwNTAnMDIuNCJTIDExOcKwNTMnMzguNCJF!5e0!3m2!1sid!2sid!4v1'),(6,11,'Arsitektur','S1','Baik Sekali','S.Ars.','4 juta','Program Studi S1 Arsitektur FATEK UNTAD adalah jenjang pendidikan sarjana akademik yang berfokus pada penggabungan ilmu arsitektur (seni dan desain) dengan teknologi bangunan serta mitigasi kebencanaan. Mahasiswa dibekali keahlian mendalam dalam merancang estetika bangunan, menganalisis struktur dan sains bangunan, menyusun tata ruang kawasan yang ramah lingkungan, serta mengintegrasikan kearifan lokal Nusantara untuk menciptakan lingkungan binaan yang aman, fungsional, dan berkelanjutan di era modern.','VISI : Pada Tahun 2020 Mampu Menghasilkan Alumni yang Unggul di Indonesia dalam Bidang Kajian dan Penerapan Rekayasa Disain berbasis Arsitektur Nusantara. MISI : 1. Pendidikan : kemampuan akademik, ber-etika, serta memiliki kompetens terutama pada disain yang berbasis arsitektur nusantara. 2. Penelitian dalam bidang arsitektur berbasis arsitektur nusantara. 3. Pengabdian kepada masyarakat untuk mengembangkan & menyebar luaskan hasil-hasil inovasi bidang arsitektur',NULL,NULL,'SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(8,5,'Bimbingan dan Konseling','S1','Unggul','S.Pd.','Rp 3.000.000','Program studi di bawah Jurusan Ilmu Pendidikan FKIP UNTAD yang berfokus pada pengembangan ilmu dan praktik layanan bimbingan serta konseling. Mahasiswa dilatih untuk memahami perkembangan psikologis individu, teknik konseling (pribadi, sosial, belajar, dan karier), asesmen psikologis non-tes maupun tes, serta manajemen layanan BK di lingkungan pendidikan maupun non-pendidikan.','VISI KEILMUAN:\n\"FKIP Universitas Tadulako menjadi Fakultas berstandar internasional dalam pengembangan IPTEKS dan Pendidikan Keguruan berwawasan lingkungan hidup.\"\n\nMISI:\n1. Menyelenggarakan pendidikan yang bermutu, modern, dan berkarakter di bidang bimbingan dan konseling.\n2. Mengembangkan penelitian inovatif dalam bidang ilmu pendidikan serta layanan bimbingan dan konseling.\n3. Menyelenggarakan pengabdian kepada masyarakat untuk mendukung pengembangan potensi dan kesejahteraan psikologis peserta didik.','Psikologi Pendidikan, Landasan Pendidikan, Kurikulum Pembelajaran, Dasar-Dasar Bimbingan dan Konseling, Teori dan Pendekatan Konseling, Konseling Individual & Kelompok, Bimbingan Karier, Asesmen Teknik Tes dan Non-Tes, Konseling Lintas Budaya, Praktikum Laboratorium Konseling, Pengenalan Lapangan Persekolahan (PLP)','Guru BK / Konselor Sekolah, Staf Pengembangan SDM (HRD), Konselor Lembaga Sosial & Pusat Rehabilitasi, Akademisi / Peneliti','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(9,5,'Pendidikan Guru Sekolah Dasar (PGSD)','S1','Unggul','S.Pd.','Rp 3.000.000','Program studi di bawah Jurusan Ilmu Pendidikan FKIP UNTAD yang berfokus mencetak calon guru kelas Sekolah Dasar yang menguasai lima bidang studi utama SD serta pengembangan media pembelajaran digital modern seperti aplikasi berbasis Android, video pembelajaran, dan Augmented Reality.','VISI KEILMUAN:\n\"Menghasilkan lulusan guru Sekolah Dasar yang berkualitas, profesional, berintegritas, dan berdaya saing di era digital melalui implementasi Tri Dharma Perguruan Tinggi.\"\n\nMISI:\n1. Menyelenggarakan pendidikan dan pembelajaran yang berkualitas untuk mencetak calon guru kelas SD yang profesional dan adaptif terhadap teknologi digital.\n2. Melaksanakan penelitian inovatif di bidang pendidikan dasar dan pengembangan media pembelajaran.\n3. Menyelenggarakan pengabdian kepada masyarakat untuk meningkatkan mutu pendidikan dasar.','Matematika Dasar, Konsep Dasar Sains/IPA SD, Konsep Dasar IPS SD, Bahasa dan Sastra Indonesia SD, Konsep Dasar PKn SD, Perkembangan Peserta Didik, Teknologi Pembelajaran, Aplikasi Mobile Learning, Pendidikan Karakter dan Antikorupsi, Seni Rupa/Kriya, Pengenalan Lapangan Persekolahan (PLP)','Guru Kelas Sekolah Dasar (SD/MI), Pengembang Media Pembelajaran & Bahan Ajar Digital, Pengelola Lembaga Pendidikan Dasar / Bimbel, Tenaga Kependidikan Dinas Pendidikan','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(10,5,'Pendidikan Guru Pendidikan Anak Usia Dini (PG-PAUD)','S1','Unggul','S.Pd.','Rp 2.500.000','Program studi di bawah Jurusan Ilmu Pendidikan FKIP UNTAD yang menyiapkan pendidik profesional di bidang pendidikan anak usia dini dengan kompetensi pedagogik, pemahaman perkembangan anak, serta keterampilan komunikasi yang adaptif terhadap perkembangan terkini.','VISI KEILMUAN:\n\"Menjadi pusat pengembangan pendidikan anak usia dini yang unggul, profesional, dan berdaya saing.\"\n\nMISI:\n1. Menyelenggarakan pendidikan dan pembelajaran anak usia dini berbasis Outcome-Based Education (OBE) yang bermutu dan adaptif.\n2. Mengembangkan penelitian inovatif di bidang pendidikan dan tumbuh kembang anak usia dini.\n3. Melaksanakan pengabdian kepada masyarakat dalam meningkatkan kualitas layanan pendidikan anak usia dini.','Psikologi Perkembangan Anak Usia Dini, Pengembangan Kognitif Anak, Pengembangan Motorik Anak, Pengembangan Seni & Kreativitas Anak, Pengembangan Bahasa Anak, Pembelajaran Berbasis Bermain, Asesmen Perkembangan Anak Usia Dini, Praktik Mengajar di Satuan PAUD/TK','Pendidik / Guru PAUD & Taman Kanak-Kanak (TK), Pengelola / Konsultan Lembaga PAUD, Pengembang Alat Permainan Edukatif (APE), Pengembang Media Stimulasi Tumbuh Kembang Anak','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(11,5,'Pendidikan Jasmani, Kesehatan, dan Rekreasi (PJKR)','S1','Unggul','S.Pd.','Rp 3.000.000','Program studi di bawah Jurusan Ilmu Pendidikan FKIP UNTAD yang berfokus pada pengembangan pendidikan jasmani, ilmu keolahragaan, kesehatan sekolah, dan aktivitas rekreasi untuk membentuk tenaga pendidik maupun peneliti olahraga yang profesional.','VISI KEILMUAN:\n\"Menjadi pusat pengembangan pendidikan Jasmani, Kesehatan dan Rekreasi yang adaptif terhadap perkembangan IPTEKS.\"\n\nMISI:\n1. Menyelenggarakan pendidikan jasmani, kesehatan, dan rekreasi yang bermutu untuk menghasilkan pendidik berkarakter dengan penguasaan pedagogi serta keterampilan olahraga yang kreatif dan inovatif.\n2. Mengembangkan penelitian keolahragaan yang inovatif dan berintegritas dengan menguasai teori dasar keolahragaan serta metodologi penelitian ilmiah.\n3. Melaksanakan pengabdian kepada masyarakat di bidang pendidikan jasmani, kesehatan, dan keolahragaan.','Anatomi, Fisiologi Olahraga, Perkembangan Motorik, Ilmu Gizi Olahraga, Pencegahan Cedera, Atletik, Permainan Bola Besar & Kecil, Senam, Beladiri, Renang, Pengenalan Lapangan Persekolahan (PLP)','Guru Pendidikan Jasmani, Olahraga, dan Kesehatan (PJOK), Pelatih / Instruktur Olahraga & Kebugaran, Pengelola Kegiatan Rekreasi & Wisata Olahraga (Sport Tourism), Tenaga Keolahragaan Instansi Pemerintah (Dispora / KONI)','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(12,5,'Pendidikan Bahasa dan Sastra Indonesia','S1','Unggul','S.Pd.','Rp 2.500.000','Program studi di bawah Jurusan Pendidikan Bahasa dan Seni FKIP UNTAD yang berfokus pada penguasaan ilmu kebahasaan (linguistik), kesastraan Indonesia, keterampilan berbahasa (menyimak, berbicara, membaca, menulis), serta metodologi pengajaran Bahasa Indonesia.','VISI KEILMUAN:\n\"Menjadi program studi unggulan dalam menghasilkan pendidik dan asisten peneliti bahasa, sastra, serta pembelajaran Bahasa Indonesia yang berakhlak mulia, cerdas, mandiri, dan profesional.\"\n\nMISI:\n1. Menyelenggarakan pendidikan bahasa dan sastra Indonesia yang bermutu untuk menghasilkan calon pendidik yang berakhlak mulia, religius, cerdas, mandiri, dan profesional.\n2. Mengembangkan penelitian di bidang kebahasaan, kesastraan, dan pembelajaran bahasa Indonesia untuk menghasilkan asisten peneliti yang berkarakter.\n3. Melaksanakan pengabdian kepada masyarakat di bidang bahasa, sastra, dan pengajaran Bahasa Indonesia.','Fonologi, Morfologi, Sintaksis, Semantik, Pragmatik, Teori Sastra, Sejarah Sastra, Apresiasi Prosa/Puisi/Drama, Keterampilan Berbahasa Indonesia, Perencanaan Pembelajaran Bahasa dan Sastra Indonesia, Evaluasi Pembelajaran, Pengajaran BIPA, Pengenalan Lapangan Persekolahan (PLP)','Guru Mata Pelajaran Bahasa Indonesia, Pengajar BIPA, Editor, Penulis, Jurnalis, Copywriter, Asisten Peneliti Kebahasaan dan Kesastraan','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(13,5,'Pendidikan Bahasa Inggris','S1','Unggul','S.Pd.','Rp 3.000.000','Program studi di bawah Jurusan Pendidikan Bahasa dan Seni FKIP UNTAD yang berfokus pada penguasaan empat keterampilan berbahasa Inggris (Listening, Speaking, Reading, Writing), ilmu linguistik, kesastraan Inggris, serta metodologi pengajaran Bahasa Inggris sebagai bahasa asing (TEFL/TESOL).','VISI KEILMUAN:\n\"Menjadi program studi pendidikan keguruan Bahasa Inggris berstandar internasional yang unggul, profesional, berkarakter, dan adaptif terhadap perkembangan teknologi informasi.\"\n\nMISI:\n1. Menyelenggarakan pendidikan dan pengajaran Bahasa Inggris berbasis Outcome-Based Education (OBE) yang bermutu dan berstandar internasional.\n2. Mengembangkan penelitian inovatif di bidang linguistik, kesastraan, dan pengajaran Bahasa Inggris (TEFL/TESOL).\n3. Melaksanakan pengabdian kepada masyarakat di bidang pendidikan, kebahasaan, dan komunikasi bahasa Inggris.','Intensive English, Listening, Speaking, Reading, Academic Writing, Phonology, Morphology, Syntax, Semantics, Sociolinguistics, Teaching English as a Foreign Language (TEFL), Curriculum and Material Development, Language Testing and Assessment, English for Specific Purposes (ESP), Pengenalan Lapangan Persekolahan (PLP)','Guru Mata Pelajaran Bahasa Inggris, Instruktur Bahasa Inggris, Penerjemah (Translator) & Juru Bahasa (Interpreter), Content Writer, Editor, Staf Komunikasi Internasional','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(14,5,'Pendidikan Matematika','S1','Unggul','S.Pd.','Rp 3.000.000','Berdiri sejak tahun 1981 di bawah Jurusan Pendidikan Matematika dan Ilmu Pengetahuan Alam (PMIPA) FKIP UNTAD. Program studi ini berfokus pada penguasaan konsep matematika murni maupun terapan, psikologi belajar matematika, serta inovasi teknologi dan metodologi pembelajaran matematika di tingkat sekolah.','VISI KEILMUAN:\n\"Menjadi program studi pendidikan matematika yang unggul dan berstandar internasional dalam pengembangan IPTEKS serta pembelajaran matematika yang berwawasan lingkungan hidup.\"\n\nMISI:\n1. Menyelenggarakan pendidikan dan pembelajaran matematika yang bermutu dan adaptif terhadap perkembangan IPTEKS.\n2. Mengembangkan penelitian di bidang pendidikan matematika dan matematika terapan yang berwawasan lingkungan hidup.\n3. Melaksanakan pengabdian kepada masyarakat di bidang pendidikan matematika dan pemberdayaan masyarakat.','Kalkulus (Diferensial, Integral, Peubah Banyak), Aljabar Linear Elementer, Struktur Aljabar, Geometri (Bidang, Ruang, Analitik, Transformasi), Analisis Real, Persamaan Diferensial, Statistika Matematika, Matematika Diskrit, Strategi Pembelajaran Matematika, Perencanaan dan Evaluasi Pembelajaran Matematika, Media Pembelajaran & Pemrograman Komputer untuk Matematika, Telaah Kurikulum Matematika Sekolah, Pengenalan Lapangan Persekolahan (PLP)','Guru Mata Pelajaran Matematika, Instruktur / Tentor Matematika, Analis Data & Statistisi Junior, Akademisi / Peneliti','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(15,5,'Pendidikan Fisika','S1','Unggul','S.Pd.','Rp 3.000.000','Berdiri sejak tahun 1989 di bawah Jurusan PMIPA FKIP UNTAD. Program studi ini berfokus pada penguasaan konsep fisika teoretis, eksperimen laboratorium fisika sekolah, serta pengembangan perangkat dan media pembelajaran fisika yang berwawasan lingkungan hidup.','VISI KEILMUAN:\n\"Menjadi program studi pendidikan fisika yang unggul dalam pengembangan ilmu pengetahuan, teknologi, dan pembelajaran fisika yang berwawasan lingkungan hidup.\"\n\nMISI:\n1. Menyelenggarakan pendidikan dan pembelajaran fisika yang bermutu berbasis eksperimen dan perkembangan IPTEKS.\n2. Mengembangkan penelitian inovatif di bidang pendidikan fisika dan pembelajaran sains.\n3. Melaksanakan pengabdian kepada masyarakat di bidang pendidikan fisika dan pemberdayaan masyarakat.','Fisika Dasar, Mekanika, Termodinamika, Gelombang & Optik, Elektromagnetika, Fisika Modern, Fisika Kuantum, Elektronika Dasar, Strategi & Evaluasi Pembelajaran Fisika, Pengenalan Lapangan Persekolahan (PLP)','Guru Fisika SMP/SMA/SMK, Laboran / Teknisi Laboratorium Fisika, Tentor Bimbingan Belajar, Asisten Peneliti Pendidikan Sains','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(16,5,'Pendidikan Kimia','S1','Unggul','S.Pd.','Rp 3.000.000','Program studi di bawah Jurusan PMIPA FKIP UNTAD yang berfokus pada penguasaan ilmu kimia (organik, anorganik, analitik, fisik, dan biokimia), pengelolaan laboratorium kimia sekolah, serta inovasi pembelajaran kimia berbasis kurikulum nasional.','VISI KEILMUAN:\n\"Menjadi program studi pendidikan kimia yang unggul dalam pengembangan ilmu kimia dan pembelajaran kimia yang berwawasan lingkungan hidup.\"\n\nMISI:\n1. Menyelenggarakan pendidikan dan pembelajaran kimia yang bermutu, modern, dan berstandar internasional.\n2. Mengembangkan penelitian inovatif di bidang pendidikan kimia serta pengelolaan laboratorium pendidikan.\n3. Melaksanakan pengabdian kepada masyarakat di bidang pendidikan kimia dan penerapan ilmu kimia bagi masyarakat.','Kimia Dasar, Kimia Organik, Kimia Anorganik, Kimia Analitik (Kualitatif & Kuantitatif), Kimia Fisika, Biokimia, Pengelolaan Laboratorium Kimia, Strategi Pembelajaran Kimia, Pengenalan Lapangan Persekolahan (PLP)','Guru Kimia SMA/SMK, Analis Laboratorium Kimia / Industri, Pengelola Laboratorium Sekolah / Kampus, Asisten Peneliti Pendidikan Kimia','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(17,5,'Pendidikan Biologi','S1','Unggul','S.Pd.','Rp 3.000.000','Salah satu prodi perintis Jurusan PMIPA FKIP UNTAD sejak tahun 1981. Berfokus pada kajian ilmu hayati, ekologi dan keanekaragaman hayati Sulawesi, praktikum biologi, serta pengembangan pembelajaran biologi berwawasan lingkungan hidup.','VISI KEILMUAN:\n\"Menjadi program studi pendidikan biologi yang unggul dalam pengembangan ilmu hayati dan pembelajaran biologi yang berwawasan lingkungan hidup.\"\n\nMISI:\n1. Menyelenggarakan pendidikan dan pembelajaran biologi yang bermutu dengan memadukan kajian keanekaragaman hayati dan inovasi pedagogik.\n2. Mengembangkan penelitian inovatif di bidang pendidikan biologi, ekologi, dan konservasi lingkungan hidup.\n3. Melaksanakan pengabdian kepada masyarakat dalam bidang pendidikan biologi dan pelestarian lingkungan hidup.','Biologi Umum, Botani, Zoologi, Anatomi & Fisiologi Tumbuhan/Hewan, Mikrobiologi, Genetika, Ekologi, Evolusi, Bioteknologi, Metodologi Pembelajaran Biologi, Pengenalan Lapangan Persekolahan (PLP)','Guru Biologi / IPA SMP & SMA/SMK, Asisten Peneliti Konservasi / Lingkungan Hidup, Pengelola Laboratorium Biologi, Edukator Sains','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(18,5,'Pendidikan Ilmu Pengetahuan Alam (IPA)','S1','Baik','S.Pd.','Rp 3.000.000','Program studi di bawah Jurusan Pendidikan MIPA (PMIPA) FKIP UNTAD yang berfokus pada pembelajaran sains terpadu (memadukan konsep fisika, kimia, dan biologi secara holistik untuk jenjang pendidikan dasar dan menengah) serta pengembangan literasi sains berwawasan lingkungan hidup.','VISI KEILMUAN:\n\"Menjadi program studi pendidikan IPA yang unggul dalam pengembangan literasi sains dan pembelajaran IPA terpadu yang berwawasan lingkungan hidup.\"\n\nMISI:\n1. Menyelenggarakan pendidikan dan pembelajaran IPA terpadu yang bermutu dan adaptif terhadap perkembangan IPTEKS.\n2. Mengembangkan penelitian inovatif di bidang pendidikan IPA terpadu dan literasi sains.\n3. Melaksanakan pengabdian kepada masyarakat di bidang pendidikan sains dan pelestarian lingkungan hidup.','IPA Terpadu, Konsep Dasar Fisika/Kimia/Biologi Sekolah, Ekologi & Ilmu Lingkungan, Praktikum IPA Terpadu, Strategi & Asesmen Pembelajaran IPA, Pengenalan Lapangan Persekolahan (PLP)','Guru IPA Terpadu SMP/MTs, Pengembang Media / Alat Peraga Sains Sekolah, Tentor Bimbingan Belajar, Edukator Lingkungan Hidup','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(19,5,'Pendidikan Pancasila dan Kewarganegaraan (PPKn)','S1','Unggul','S.Pd.','Rp 3.000.000','Program studi di bawah Jurusan Pendidikan Ilmu Pengetahuan Sosial (PIPS) FKIP UNTAD yang berfokus pada kajian Pancasila, hukum tata negara, ilmu politik, hak asasi manusia (HAM), serta pendidikan karakter dan kewarganegaraan untuk mencetak pendidik PPKn yang berintegritas.','VISI KEILMUAN:\n\"Menjadi program studi pendidikan Pancasila dan kewarganegaraan yang unggul dalam mencetak pendidik berkarakter, demokratis, dan berintegritas.\"\n\nMISI:\n1. Menyelenggarakan pendidikan kewarganegaraan yang bermutu untuk menghasilkan pendidik PPKn yang profesional dan berkarakter.\n2. Mengembangkan penelitian di bidang pendidikan Pancasila, hukum, politik, dan kewarganegaraan.\n3. Melaksanakan pengabdian kepada masyarakat dalam penguatan nilai-nilai kebangsaan, demokrasi, dan kesadaran hukum.','Pendidikan Pancasila, Ilmu Kewarganegaraan, Ilmu Negara, Hukum Tata Negara, Sistem Politik Indonesia, Pendidikan HAM dan Demokrasi, Hukum Pidana & Perdata Dasar, Strategi Pembelajaran PPKn, Pengenalan Lapangan Persekolahan (PLP)','Guru PPKn SMP dan SMA/SMK, Staf Administrasi / Analis Kebijakan Publik, Konsultan LSM Hukum & Demokrasi, Akademisi','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(20,5,'Pendidikan Sejarah','S1','Unggul','S.Pd.','Rp 3.000.000','Berdiri sejak tahun 1966 di bawah Jurusan Pendidikan IPS FKIP UNTAD. Didukung laboratorium sejarah, perpustakaan digital, serta ruang multimedia untuk mengkaji historiografi, sejarah lokal Sulawesi Tengah, sejarah nasional, dan pembelajaran sejarah kreatif.','VISI KEILMUAN:\n\"Menjadi program studi pendidikan sejarah yang unggul dalam kajian historiografi, pelestarian sejarah lokal dan nasional, serta inovasi pembelajaran sejarah.\"\n\nMISI:\n1. Menyelenggarakan pendidikan dan pembelajaran sejarah yang bermutu, kreatif, dan berbasis teknologi.\n2. Mengembangkan penelitian di bidang pendidikan sejarah, historiografi, dan sejarah lokal Sulawesi Tengah.\n3. Melaksanakan pengabdian kepada masyarakat dalam pelestarian cagar budaya, kearsipan, dan kesadaran sejarah.','Pengantar Ilmu Sejarah, Historiografi, Sejarah Indonesia (Prasejarah hingga Reformasi), Sejarah Sulawesi Tengah, Sejarah Asia & Eropa, Museologi & Kearsipan, Metodologi Penelitian Sejarah, Perencanaan Pembelajaran Sejarah, Pengenalan Lapangan Persekolahan (PLP)','Guru Sejarah SMA/SMK dan IPS SMP, Peneliti Sejarah dan Budaya, Kurator Museum, Arsiparis Instansi Pemerintah / Swasta, Konsultan Sejarah & Pariwisata Budaya','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(21,5,'Pendidikan Geografi','S1','Unggul','S.Pd.','Rp 3.000.000','Program studi di bawah Jurusan Pendidikan IPS FKIP UNTAD yang berfokus pada ilmu kebumian, geografi fisik dan manusia, pemetaan digital (SIG/Penginderaan Jauh), mitigasi kebencanaan, serta pembelajaran geografi berwawasan lingkungan hidup.','VISI KEILMUAN:\n\"Menjadi program studi pendidikan geografi yang unggul dalam penguasaan ilmu kebumian, pemetaan digital, mitigasi kebencanaan, dan pembelajaran geografi berwawasan lingkungan hidup.\"\n\nMISI:\n1. Menyelenggarakan pendidikan dan pembelajaran geografi yang bermutu berbasis teknologi geospasial dan wawasan lingkungan.\n2. Mengembangkan penelitian di bidang pendidikan geografi, geospasial, dan mitigasi kebencanaan.\n3. Melaksanakan pengabdian kepada masyarakat dalam pemetaan wilayah, edukasi kebencanaan, dan pelestarian lingkungan.','Geologi & Geomorfologi, Meteorologi & Klimatologi, Hidrologi & Oseanografi, Kartografi, Sistem Informasi Geografis (SIG), Penginderaan Jauh, Geografi Manusia & Pembangunan Wilayah, Pendidikan Kebencanaan, Metodologi Pembelajaran Geografi, Pengenalan Lapangan Persekolahan (PLP)','Guru Geografi SMA/SMK dan IPS SMP, Analis Pemetaan / GIS (Geographic Information System), Konsultan Tata Ruang dan Lingkungan','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(22,5,'Pendidikan Kepelatihan Olahraga (PKO)','S1','Baik','S.Pd.','Rp 5.000.000','Program studi di bawah Jurusan Ilmu Pendidikan FKIP UNTAD yang berdiri pada tahun 2025. Berfokus pada ilmu kepelatihan fisik dan teknik cabang olahraga, manajemen tim atau klub olahraga, analisis performa atlet berbasis IPTEKS, serta pedagogi olahraga yang berwawasan lingkungan hidup.','VISI KEILMUAN:\n\"Menjadi program studi pendidikan kepelatihan olahraga yang unggul dalam pengembangan ilmu kepelatihan, analisis performa atlet, dan keolahragaan yang berwawasan lingkungan hidup.\"\n\nMISI:\n1. Menyelenggarakan pendidikan kepelatihan olahraga yang bermutu dan adaptif terhadap perkembangan IPTEKS.\n2. Mengembangkan penelitian di bidang ilmu kepelatihan, kebugaran, dan performa atlet.\n3. Melaksanakan pengabdian kepada masyarakat di bidang pembinaan olahraga dan kesehatan jasmani.','Anatomi & Fisiologi Latihan, Metodologi Kepelatihan Olahraga, Gizi & Pemulihan Cedera Olahraga, Tes & Pengukuran Olahraga, Psikologi Kepelatihan, Spesialisasi Cabang Olahraga (Atletik, Permainan, Beladiri, Akuatik), Praktik Kepelatihan Lapangan','Pelatih Cabang Olahraga (Coach), Pelatih Fisik (Strength & Conditioning Coach), Guru PJOK SD/SMP/SMA/SMK, Analis Performa Atlet & Manajer Event Olahraga','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(23,5,'Magister Pendidikan Bahasa Inggris','S2','Unggul','M.Pd.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Berdiri sejak tahun 2006 di Gedung A Pascasarjana UNTAD. Program studi ini dirancang untuk meningkatkan kompetensi pedagogik, keilmuan kebahasaan, serta kecakapan berbahasa Inggris tingkat lanjut guna menjawab kebutuhan sumber daya manusia global di Sulawesi Tengah.','VISI KEILMUAN:\n\"Menjadi program studi magister pendidikan bahasa Inggris yang unggul dan berdaya saing global dalam pengembangan keilmuan kebahasaan, pedagogi, dan riset pembelajaran bahasa Inggris.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister berbasis Outcome-Based Education (OBE) untuk meningkatkan profesionalitas pendidik dan peneliti bahasa Inggris.\n2. Mengembangkan riset inovatif pada bidang kurikulum dan materi, metodologi pengajaran, evaluasi dan asesmen, kajian sastra, kajian linguistik, serta pengembangan keprofesian guru.\n3. Melaksanakan pengabdian kepada masyarakat dan diseminasi publikasi ilmiah di bidang pendidikan bahasa Inggris.','Philosophy of Science and Research Methodology, Advanced Language Components and Skills, Curriculum and Instructional Design, Applied Sociolinguistics, Research Design, Strategies in Translation and Interpretation, Applied Statistics, TPACK in TEFL, Assessments in ELT, Quantitative and Qualitative Data Analysis, Teaching Practicum, Writing for Publication, Seminar on English Education, Tesis','Dosen Pendidikan Bahasa Inggris / Bahasa Inggris Umum, Guru Profesional / Guru Penggerak / Kepala Sekolah, Pengembang Kurikulum & Instruktur Bahasa Inggris, Peneliti Pendidikan Bahasa & Linguistik Terapan, Translator / Interpreter','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(24,5,'Magister Pendidikan Bahasa Indonesia','S2','Baik Sekali','M.Pd.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Memperoleh izin operasional sejak tahun 2011 dan dikelola di bawah FKIP UNTAD. Program studi ini bertujuan menghasilkan lulusan berkualifikasi magister yang kompeten sebagai dosen, guru profesional, peneliti kebahasaan maupun kesastraan, serta pengembang kurikulum pembelajaran Bahasa Indonesia.','VISI KEILMUAN:\n\"Menjadi program studi magister pendidikan bahasa Indonesia yang unggul dan profesional dalam pengembangan keilmuan kebahasaan, kesastraan, serta pembelajaran Bahasa Indonesia.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister bahasa dan sastra Indonesia yang bermutu untuk menghasilkan dosen, guru profesional, dan pengembang kurikulum.\n2. Mengembangkan penelitian inovatif di bidang kebahasaan, kesastraan, dan pembelajaran Bahasa Indonesia.\n3. Melaksanakan pengabdian kepada masyarakat dan diseminasi publikasi ilmiah di bidang pendidikan bahasa dan sastra Indonesia.','Filsafat Ilmu & Metodologi Penelitian Pendidikan Bahasa, Linguistik Terapan & Kajian Wacana, Teori & Apresiasi Sastra Mutakhir, Pengembangan Kurikulum & Bahan Ajar Bahasa Indonesia, Evaluasi Pembelajaran Bahasa, Penulisan Karya Ilmiah / Publikasi Jurnal, Tesis','Dosen Pendidikan Bahasa Indonesia, Guru Profesional SMP/SMA/SMK, Pengajar BIPA Tingkat Lanjut, Editor / Konsultan Bahasa & Penerbitan, Peneliti Kebahasaan dan Sastra','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(25,5,'Magister Pendidikan Sains','S2','Baik Sekali','M.Pd.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Berdiri sejak tahun 2009 di bawah naungan Pascasarjana dan FKIP UNTAD. Program studi ini berorientasi pada pengembangan kompetensi akademik dan profesional pendidikan sains (mencakup konsentrasi IPA, Fisika, Kimia, dan Biologi) melalui pendekatan interdisipliner berwawasan lingkungan.','VISI KEILMUAN:\n\"Menjadi program studi magister pendidikan sains yang unggul dalam pengembangan kompetensi akademik, penelitian interdisipliner, dan pembelajaran sains yang berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister pendidikan sains yang bermutu dengan pendekatan interdisipliner berwawasan lingkungan.\n2. Mengembangkan penelitian inovatif di bidang pendidikan IPA, Fisika, Kimia, dan Biologi.\n3. Melaksanakan pengabdian kepada masyarakat dalam meningkatkan literasi sains dan kualitas pendidikan sains.','Filsafat Ilmu, Metodologi Penelitian Pendidikan Sains, Kajian Konsep Lanjut Sains (IPA/Fisika/Kimia/Biologi), Pengembangan Kurikulum & Pembelajaran Sains, Asesmen Pembelajaran Sains, Tesis','Dosen Pendidikan Sains, Guru Profesional Sains (IPA/Fisika/Kimia/Biologi), Peneliti Pendidikan Sains, Pengembang Kurikulum Sains','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(26,5,'Magister Pendidikan Ilmu Pengetahuan Sosial (IPS)','S2','Baik Sekali','M.Pd.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi jenjang magister di bawah Pascasarjana dan FKIP UNTAD yang berfokus pada pengembangan kompetensi pedagogik, kajian multidisiplin ilmu sosial (Geografi, Sejarah, Ekonomi, Sosiologi, dan PKn), serta penelitian kebijakan sosial-pendidikan berorientasi IPTEKS.','VISI KEILMUAN:\n\"Menghasilkan lulusan Magister Pendidikan IPS yang handal dalam pembelajaran dan penelitian berorientasi IPTEKS.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister untuk menguatkan kualitas sumber daya manusia berbasis hakikat Pendidikan IPS.\n2. Mengembangkan riset kebijakan sosial-pendidikan dan pembelajaran IPS yang inovatif.\n3. Melaksanakan pengabdian kepada masyarakat di bidang pendidikan ilmu pengetahuan sosial.','Filsafat Ilmu, Metodologi Penelitian & Kebijakan Sosial, Epistemologi Pendidikan IPS, Kajian Multidisiplin Ilmu Sosial (Geografi, Sejarah, Ekonomi, Sosiologi, PKn), Tesis','Dosen Pendidikan IPS, Guru Profesional IPS / Sejarah / Geografi / PPKn, Peneliti Kebijakan Sosial-Pendidikan, Konsultan Pendidikan Sosial','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(27,5,'Magister Pendidikan Matematika','S2','Baik Sekali','M.Pd.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi di bawah Pascasarjana dan FKIP UNTAD yang berorientasi pada pendalaman teori matematika lanjut, psikologi kognitif pembelajaran matematika, serta riset inovasi pembelajaran matematika berwawasan lingkungan hidup.','VISI KEILMUAN:\n\"Menjadi program studi magister pendidikan matematika yang unggul dalam pengembangan teori matematika lanjut, riset pembelajaran, dan pendidikan matematika berwawasan lingkungan hidup.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister pendidikan matematika yang bermutu dan adaptif terhadap perkembangan IPTEKS.\n2. Mengembangkan penelitian inovatif di bidang pendidikan matematika dan psikologi kognitif pembelajaran matematika.\n3. Melaksanakan pengabdian kepada masyarakat dalam meningkatkan mutu pembelajaran matematika di satuan pendidikan.','Filsafat Ilmu & Metodologi Penelitian Pendidikan Matematika, Analisis Real & Aljabar Lanjut, Kapita Selekta Matematika Sekolah, Pengembangan Kurikulum & Asesmen Matematika, Pemodelan Matematika, Penulisan Karya Ilmiah, Tesis','Dosen Pendidikan Matematika / Matematika Dasar, Guru Profesional SMP/SMA/SMK, Peneliti Pendidikan Matematika, Pengembang Kurikulum dan Bahan Ajar','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(28,5,'Magister Pendidikan Sejarah','S2','Terakreditasi','M.Pd.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi pascasarjana kependidikan di bawah Pascasarjana dan FKIP UNTAD yang berfokus pada kajian historiografi tingkat lanjut, sejarah lokal kawasan Sulawesi dan Indonesia Timur, sejarah sosial-budaya, serta metodologi pengajaran sejarah yang kritis dan kontekstual.','VISI KEILMUAN:\n\"Menjadi program studi magister pendidikan sejarah yang unggul dalam kajian historiografi lanjut, sejarah lokal Sulawesi dan Indonesia Timur, serta inovasi pembelajaran sejarah.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister pendidikan sejarah yang bermutu, kritis, dan kontekstual.\n2. Mengembangkan penelitian di bidang historiografi, sejarah sosial-budaya, sejarah lokal, dan pembelajaran sejarah.\n3. Melaksanakan pengabdian kepada masyarakat dalam pelestarian cagar budaya, kearsipan, dan edukasi sejarah.','Filsafat Ilmu & Filsafat Sejarah, Historiografi Indonesia & Global, Metodologi Penelitian Sejarah & Pendidikan Sejarah, Sejarah Lokal Sulawesi Tengah, Pengembangan Kurikulum & Media Pembelajaran Sejarah, Tesis','Dosen Pendidikan Sejarah / Ilmu Sejarah, Guru Sejarah Profesional SMA/SMK, Peneliti Sejarah dan Kebudayaan, Kurator Museum, Konsultan Kearsipan dan Cagar Budaya','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(29,5,'Magister Pendidikan Dasar','S2','Baik','M.Pd.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi pascasarjana di FKIP UNTAD yang dibuka pada tahun 2026 untuk menjawab kebutuhan peningkatan kualifikasi guru SD/MI, kepala sekolah dasar, dan pengawas satuan pendidikan dasar di Sulawesi Tengah.','VISI KEILMUAN:\n\"Menjadi program studi magister pendidikan dasar yang unggul dalam pengembangan pedagogi, kepemimpinan sekolah dasar, dan inovasi pembelajaran dasar.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister pendidikan dasar yang bermutu untuk meningkatkan kompetensi guru, kepala sekolah, dan pengawas satuan pendidikan dasar.\n2. Mengembangkan penelitian inovatif di bidang kurikulum, asesmen, dan pembelajaran tematik terpadu di sekolah dasar.\n3. Melaksanakan pengabdian kepada masyarakat untuk peningkatan mutu pendidikan dasar.','Filsafat Ilmu Pendidikan, Metodologi Penelitian Pendidikan Dasar, Kajian Pedagogi & Pembelajaran Tematik Terpadu SD, Pengembangan Kurikulum & Asesmen Pendidikan Dasar, Manajemen & Kepemimpinan Sekolah Dasar, Inovasi Pembelajaran Digital SD, Tesis','Dosen PGSD, Guru SD/MI Berkualifikasi Magister, Kepala Sekolah Dasar, Pengawas Satuan Pendidikan Dasar, Pengembang Kebijakan dan Kurikulum Pendidikan Dasar','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(30,5,'Doktor Pendidikan Sains','S3','B','Dr.','Rp 12.000.000 (Matrikulasi Rp 1.000.000)','Berdiri sejak tahun 2015 di bawah naungan Pascasarjana dan FKIP UNTAD. Program studi jenjang doktoral yang berfokus pada kajian multi dan transdisiplin pendidikan sains serta pengembangan riset pendidikan MIPA bertaraf internasional yang berwawasan lingkungan alami.','VISI KEILMUAN:\n\"Menghasilkan Doktor Pendidikan Sains Bertaraf Internasional yang Berwawasan Lingkungan Alami.\"\n\nMISI:\n1. Menyelenggarakan pendidikan doktoral pendidikan sains yang bermutu dan bertaraf internasional.\n2. Mengembangkan penelitian multi dan transdisiplin di bidang pendidikan sains yang berwawasan lingkungan alami serta dipublikasikan pada jurnal internasional bereputasi.\n3. Melaksanakan pengabdian kepada masyarakat melalui diseminasi inovasi pendidikan sains dan kebijakan pendidikan.','Filsafat Ilmu & Metodologi Penelitian Lanjut Pendidikan Sains, Kajian Multi dan Transdisiplin Sains Berwawasan Lingkungan, Publikasi Jurnal Internasional Bereputasi, Ujian Kualifikasi, Proposal Disertasi, Seminar Hasil, Ujian Tertutup dan Terbuka Disertasi','Dosen / Guru Besar Pendidikan Sains dan MIPA, Peneliti Utama Bidang Pendidikan Sains, Konsultan Kebijakan Pendidikan Nasional','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(31,5,'Pendidikan Program Doktor','S3','Baik','Dr.','Rp 12.000.000 (Matrikulasi Rp 1.000.000)','Program studi doktor kependidikan di bawah Pascasarjana dan FKIP UNTAD yang dibuka pada tahun 2026 untuk menampung lulusan Magister (S2) dari berbagai bidang kependidikan (seperti Pendidikan Bahasa, Pendidikan IPS, Pendidikan Dasar, BK, dan Manajemen Pendidikan) agar dapat menempuh studi doktoral secara linier.','VISI KEILMUAN:\n\"Menjadi program studi doktor kependidikan yang unggul dalam pengembangan ilmu pendidikan, kebijakan pendidikan, dan inovasi pembelajaran yang berdaya saing.\"\n\nMISI:\n1. Menyelenggarakan pendidikan doktoral kependidikan yang bermutu untuk menghasilkan akademisi dan pemimpin pendidikan yang unggul.\n2. Mengembangkan riset kependidikan lanjut, kurikulum, dan kebijakan pendidikan yang dipublikasikan secara internasional.\n3. Melaksanakan pengabdian kepada masyarakat dalam meningkatkan mutu tata kelola dan praktik pendidikan.','Filsafat Ilmu Pendidikan, Metodologi Riset Kependidikan Lanjut, Pengembangan Kurikulum & Kebijakan Pendidikan, Publikasi Ilmiah Internasional, Ujian Kualifikasi, Disertasi','Dosen / Akademisi Fakultas Keguruan dan Ilmu Pendidikan, Peneliti Kebijakan Pendidikan, Pimpinan / Konsultan Lembaga Pendidikan','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(32,5,'Pendidikan Profesi Guru (PPG)','Profesi','Unggul','Gr.','Beasiswa Pemerintah / Rp 8.500.000 (Mandiri)','Berdiri sejak tahun 2018 dan dikelola melalui Sistem Informasi PPG FKIP UNTAD sebagai Lembaga Pendidikan Tenaga Kependidikan (LPTK) penyelenggara sertifikasi pendidik profesional bagi lulusan S1/D4 kependidikan maupun non-kependidikan di Sulawesi Tengah dan kawasan Indonesia Timur.','VISI KEILMUAN:\n\"Menjadi penyelenggara pendidikan profesi guru yang unggul dengan pembelajaran reflektif-kolaboratif, berbasis standar nasional pendidikan, serta terintegrasi dengan kemitraan sekolah.\"\n\nMISI:\n1. Menyelenggarakan pendidikan profesi guru yang bermutu, reflektif, dan kolaboratif berbasis standar nasional pendidikan.\n2. Mengembangkan inovasi pembelajaran, asesmen autentik, dan riset tindakan kelas dalam kemitraan dengan sekolah.\n3. Melaksanakan pengabdian kepada masyarakat untuk peningkatan profesionalitas dan kompetensi berkelanjutan guru.','Pendalaman Materi & Lokakarya, Perancangan Perangkat Pembelajaran, Asesmen Autentik, Pemanfaatan Teknologi/AI dalam Pembelajaran, Penelitian Tindakan Kelas (PTK), Praktik Pengalaman Lapangan (PPL), Uji Kompetensi Peserta Pendidikan Profesi Guru (UKPPPG)','Guru Profesional Bersertifikat Pendidik, Instruktur / Pengembang Perangkat Pembelajaran, Tenaga Kependidikan / Satuan Kerja Dinas Pendidikan','Pendaftaran terpusat nasional melalui portal PPG Kemendikdasmen (Jalur PPG Calon Guru / Prajabatan dan PPG Guru Tertentu / Dalam Jabatan).',NULL,NULL),(33,3,'Administrasi Publik','S1','Unggul','S.A.P.','Rp 2.500.000','Program studi di bawah FISIP UNTAD yang berfokus pada tata kelola organisasi publik, perumusan dan analisis kebijakan publik, serta inovasi pelayanan publik berbasis good governance.','VISI KEILMUAN:\n\"Unggul dan berdaya saing dalam Penyelenggaraan Pendidikan, Penelitian dan Pengabdian Masyarakat pada bidang Ilmu Administrasi Publik pada tingkat Nasional dan Internasional.\"\n\nMISI:\n1. Menyelenggarakan pendidikan dan pembelajaran ilmu administrasi publik berbasis Outcome-Based Education (OBE) yang bermutu dan berdaya saing.\n2. Mengembangkan penelitian inovatif di bidang kebijakan publik, manajemen pelayanan publik, dan tata kelola pemerintahan.\n3. Melaksanakan pengabdian kepada masyarakat untuk mendukung reformasi birokrasi dan kualitas pelayanan publik.','Dasar-Dasar Ilmu Administrasi Publik, Teori Organisasi, Kebijakan Publik, Manajemen Pelayanan Publik, Keuangan Negara/Daerah, Collaborative Governance, Inovasi Sektor Publik, Magang / KKN, Skripsi','Analis Kebijakan Publik, Aparatur Sipil Negara (ASN/PNS/PPPK), Staf Administrasi BUMN / Perusahaan Swasta, Konsultan Tata Kelola Pemerintahan','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(34,3,'Ilmu Pemerintahan','S1','Unggul','S.I.P.','Rp 2.500.000','Program studi di bawah FISIP UNTAD yang mengkaji struktur, proses, dinamika kekuasaan, otonomi daerah, kepemimpinan pemerintahan, serta tata kelola pemilu dan demokrasi berwawasan lingkungan.','VISI KEILMUAN:\n\"Menjadi program studi ilmu pemerintahan yang unggul dan berdaya saing dalam tata kelola pemerintahan, demokrasi, dan pemberdayaan masyarakat berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan ilmu pemerintahan yang bermutu untuk menghasilkan lulusan yang profesional dan berintegritas.\n2. Mengembangkan penelitian di bidang otonomi daerah, politik lokal, tata kelola pemilu, dan kepemimpinan pemerintahan.\n3. Melaksanakan pengabdian kepada masyarakat dalam penguatan tata kelola pemerintahan daerah dan desa.','Pengantar Ilmu Pemerintahan, Sistem Pemerintahan Indonesia, Pemerintahan Daerah & Desa, Kepemimpinan Pemerintahan, Politik Lokal & Otonomi Daerah, Manajemen Konflik Pemerintahan, Magang / KKN, Skripsi','Aparatur Pemerintah Pusat / Daerah, Staf Penyelenggara Pemilu (KPU / Bawaslu), Analis Politik dan Pemerintahan, Tenaga Pendamping Desa / Pemberdayaan Masyarakat','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(35,3,'Ilmu Komunikasi','S1','Unggul','S.I.Kom.','Rp 2.500.000','Program studi di bawah FISIP UNTAD yang berfokus pada kajian komunikasi massa, media digital, hubungan masyarakat (public relations), dan jurnalistik dengan dukungan laboratorium penyiaran dan multimedia.','VISI KEILMUAN:\n\"Menjadi program studi ilmu komunikasi yang unggul dan adaptif terhadap perkembangan teknologi media digital, penyiaran, jurnalistik, dan kehumasan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan ilmu komunikasi yang bermutu pada bidang jurnalistik, broadcasting, dan public relations.\n2. Mengembangkan penelitian inovatif di bidang komunikasi massa, media baru, dan komunikasi strategis.\n3. Melaksanakan pengabdian kepada masyarakat di bidang literasi media dan komunikasi publik.','Teori Komunikasi, Komunikasi Massa, Jurnalistik Cetak & Siber, Produksi Siaran TV/Radio, Manajemen Kampanye PR, Komunikasi Digital & Media Baru, Magang / KKN, Skripsi','Praktisi Public Relations (Humas), Jurnalis / Reporter Media Massa, Produser / Penyiar Konten Penyiaran, Digital Marketing & Social Media Specialist, Event Organizer','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(36,3,'Sosiologi','S1','Baik Sekali','S.Sos.','Rp 1.600.000','Program studi di bawah FISIP UNTAD yang mengkaji struktur sosial, perubahan masyarakat, dinamika konflik, pembangunan wilayah, dan pemberdayaan masyarakat pesisir maupun pedesaan di Sulawesi Tengah.','VISI KEILMUAN:\n\"Menjadi program studi sosiologi yang unggul dalam kajian perubahan sosial, resolusi konflik, dan pemberdayaan masyarakat pesisir maupun pedesaan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan sosiologi yang bermutu dan responsif terhadap dinamika sosial masyarakat.\n2. Mengembangkan penelitian sosial di bidang pembangunan wilayah, resolusi konflik, dan masyarakat pesisir.\n3. Melaksanakan pengabdian kepada masyarakat melalui pendampingan sosial dan pemberdayaan komunitas.','Teori Sosiologi Klasik & Modern, Metode Penelitian Sosial (Kuantitatif & Kualitatif), Sosiologi Pembangunan, Sosiologi Konflik & Resolusi Konflik, Sosiologi Pesisir & Kemasyarakatan, Analisis Dampak Sosial (ANDAL), Magang / KKN, Skripsi','Peneliti Sosial, Fasilitator / Konsultan Pemberdayaan Masyarakat & CSR, Analis Sosial Dinas Sosial / Bappeda, Pegiat LSM / NGO','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(37,3,'Antropologi Sosial','S1','Baik Sekali','S.Sos.','Rp 1.600.000','Program studi di bawah FISIP UNTAD yang mempelajari keberagaman manusia, kebudayaan, kearifan lokal etnis-etnis di Sulawesi Tengah, etnografi, serta adaptasi sosial-ekologi masyarakat terhadap lingkungan dan kebencanaan.','VISI KEILMUAN:\n\"Menjadi program studi antropologi sosial yang unggul dalam kajian etnografi, pelestarian kearifan lokal, dan adaptasi sosial-ekologi masyarakat.\"\n\nMISI:\n1. Menyelenggarakan pendidikan antropologi sosial yang bermutu dengan menekankan penguasaan riset etnografi dan kepekaan budaya.\n2. Mengembangkan penelitian kebudayaan, kearifan lokal Sulawesi Tengah, serta kajian ekologi dan kebencanaan.\n3. Melaksanakan pengabdian kepada masyarakat dalam pelestarian budaya dan mitigasi bencana berbasis komunitas.','Pengantar Antropologi, Etnografi Nusantara & Sulawesi, Metode Penelitian Etnografi, Antropologi Ekologi & Kebencanaan, Antropologi Budaya & Agama, Antropologi Kesehatan/Hukum, Magang / KKN, Skripsi','Peneliti Kebudayaan dan Etnografi (BRIN / Balai Pelestarian Kebudayaan), Konsultan Sosial-Budaya & CSR, Kurator Museum, Perancang Pariwisata Budaya & Mitigasi Bencana Berbasis Komunitas','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(38,3,'Magister Administrasi Publik','S2','B','M.A.P.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Berdiri sejak 26 Juni 2003 di bawah FISIP UNTAD dengan lebih dari 1.500 alumni di instansi pemerintah maupun swasta. Program studi ini berfokus pada tata kelola organisasi publik, perumusan dan analisis kebijakan publik, serta reformasi birokrasi berbasis good governance.','VISI KEILMUAN:\n\"Unggul dalam menyiapkan tenaga profesional di bidang Administrasi Publik yang sesuai dengan prinsip good governance.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister administrasi publik berbasis Outcome-Based Education (OBE) yang bermutu dan berdaya saing.\n2. Mengembangkan penelitian di bidang kebijakan publik, manajemen sektor publik, dan good governance.\n3. Melaksanakan pengabdian kepada masyarakat untuk mendukung tata kelola pemerintahan dan pelayanan publik yang berkualitas.','Filsafat Ilmu & Metodologi Penelitian Administrasi, Teori Administrasi Publik Lanjut, Formulasi & Evaluasi Kebijakan Publik, Manajemen Strategis Sektor Publik, Good Governance & Reformasi Birokrasi, Publikasi Karya Ilmiah, Tesis','Pejabat / Analis Kebijakan Madya, Manajer Sektor Publik / BUMN, Dosen Ilmu Administrasi Publik, Konsultan Reformasi Birokrasi','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(39,3,'Magister Ilmu Komunikasi','S2','Baik','M.I.Kom.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi jenjang magister di bawah FISIP UNTAD untuk memperdalam kajian teori komunikasi kontemporer, komunikasi strategis, manajemen media digital, serta komunikasi pembangunan dan kebencanaan yang selaras dengan visi FISIP UNTAD.','VISI KEILMUAN:\n\"Menjadi program studi magister ilmu komunikasi yang unggul dalam kajian komunikasi strategis, media digital, dan komunikasi pembangunan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister ilmu komunikasi berbasis OBE yang bermutu dan adaptif terhadap perkembangan media.\n2. Mengembangkan penelitian inovatif di bidang komunikasi strategis, media baru, dan komunikasi publik/kebencanaan.\n3. Melaksanakan pengabdian kepada masyarakat dalam penguatan literasi komunikasi dan kehumasan.','Filsafat Ilmu Komunikasi, Metodologi Penelitian Komunikasi Kuantitatif & Kualitatif, Teori Komunikasi Lanjut, Komunikasi Korporat & Strategis, Kajian Media Baru & Digital, Manajemen Krisis & Komunikasi Publik, Penulisan Jurnal Ilmiah, Tesis','Dosen Ilmu Komunikasi, Corporate Communication Manager, Konsultan Public Relations & Strategi Media, Kepala Bidang Humas / Informasi Instansi Pemerintah, Peneliti Komunikasi dan Media','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(40,3,'Magister Ilmu Pemerintahan','S2','Baik','M.I.P.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi jenjang magister di bawah FISIP UNTAD untuk menghasilkan magister yang kompeten dalam menganalisis tata kelola pemerintahan daerah, desentralisasi, kepemimpinan politik-pemerintahan, serta kebijakan otonomi daerah berbasis kearifan lokal dan wawasan lingkungan.','VISI KEILMUAN:\n\"Menjadi program studi magister ilmu pemerintahan yang unggul dalam tata kelola pemerintahan daerah, desentralisasi, dan kepemimpinan politik berbasis kearifan lokal dan wawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister ilmu pemerintahan berbasis OBE yang bermutu dan berintegritas.\n2. Mengembangkan penelitian di bidang pemerintahan daerah, politik lokal, otonomi daerah, dan inovasi pelayanan publik.\n3. Melaksanakan pengabdian kepada masyarakat untuk penguatan tata kelola pemerintahan daerah dan desa.','Filsafat Ilmu & Metodologi Penelitian Pemerintahan, Teori Pemerintahan & Kekuasaan, Tata Kelola Pemerintahan Daerah & Desa, Manajemen Pelayanan & Inovasi Pemerintahan, Politik Lokal & Demokrasi, Publikasi Ilmiah, Tesis','Dosen Ilmu Pemerintahan, Pejabat / Analis Pemerintahan (Kemendagri / Pemda / DPRD), Tenaga Ahli Legislatif / Eksekutif, Penyelenggara & Konsultan Pemilu, Peneliti Kebijakan Politik dan Pemerintahan','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(41,1,'Akuntansi Sektor Publik','D4','Unggul','S.Tr.Ak.','Rp 4.000.000','Program studi vokasi di bawah Jurusan Akuntansi Fakultas Ekonomi dan Bisnis (FEB) UNTAD yang berfokus pada tata kelola keuangan pemerintah pusat dan daerah, entitas nirlaba, serta badan layanan umum (BLUD) dengan penekanan pada keterampilan praktik kerja.','VISI KEILMUAN:\n\"Menjadi penyelenggara pendidikan vokasi akuntansi sektor publik yang unggul dan berdaya saing di kawasan Timur Indonesia dalam mendukung tata kelola pemerintahan yang transparan dan akuntabel (good governance).\"\n\nMISI:\n1. Menyelenggarakan pendidikan vokasi akuntansi sektor publik berbasis praktik yang bermutu dan berdaya saing.\n2. Mengembangkan penelitian terapan di bidang akuntansi pemerintahan, audit sektor publik, dan tata kelola keuangan publik.\n3. Melaksanakan pengabdian kepada masyarakat untuk memperkuat transparansi dan akuntabilitas pengelolaan keuangan publik.','Akuntansi Keuangan Pemerintah Daerah, Sistem Akuntansi Instansi, Penganggaran Sektor Publik, Audit Sektor Publik & Investigatif, Akuntansi Keuangan Desa, Perpajakan Sektor Publik, Praktik Kerja Lapangan (PKL), Tugas Akhir Terapan','Pengelola Keuangan / Bendahara / Analis Anggaran Instansi Pemerintah & BLUD, Auditor Sektor Publik (BPK RI / BPKP / Inspektorat / KAP), Akuntan Organisasi Nirlaba & BUMN','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(42,1,'Ekonomi dan Pembangunan','S1','Unggul','S.E.','Rp 2.500.000','Program studi di bawah Fakultas Ekonomi dan Bisnis (FEB) UNTAD yang berfokus pada analisis ekonomi makro dan mikro, perencanaan pembangunan wilayah, ekonomi publik, serta ekonomi sumber daya dan lingkungan di kawasan Timur Indonesia.','VISI KEILMUAN:\n\"Menjadi program studi ekonomi dan pembangunan yang unggul dan berdaya saing dalam perencanaan pembangunan wilayah dan ekonomi sumber daya berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan ekonomi dan pembangunan yang bermutu dan adaptif terhadap dinamika ekonomi regional maupun global.\n2. Mengembangkan penelitian inovatif di bidang perencanaan pembangunan wilayah, keuangan publik, dan ekonomi sumber daya alam/lingkungan.\n3. Melaksanakan pengabdian kepada masyarakat untuk mendukung pembangunan daerah berkelanjutan.','Teori Ekonomi Mikro & Makro, Ekonometrika, Ekonomi Pembangunan & Perencanaan Wilayah, Keuangan Negara/Daerah, Ekonomi Moneter & Perbankan, Ekonomi Sumber Daya Alam, KKN / Magang, Skripsi','Analis Kebijakan Ekonomi (Bappenas / Bappeda / Kemenkeu / Bank Indonesia / OJK), Peneliti Ekonomi, Perencana Pembangunan Daerah, Analis Riset Pasar','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(43,1,'Manajemen','S1','Unggul','S.M.','Rp 3.000.000','Program studi di bawah Fakultas Ekonomi dan Bisnis (FEB) UNTAD (Kampus Utama Palu) yang mengkaji tata kelola bisnis, kewirausahaan, manajemen strategis, dan pengambilan keputusan organisasi dengan konsentrasi pada Manajemen Keuangan, Pemasaran, Sumber Daya Manusia (SDM), dan Operasional.','VISI KEILMUAN:\n\"Menjadi program studi manajemen yang unggul dan berdaya saing dalam pengembangan ilmu manajemen dan kewirausahaan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan manajemen yang bermutu berbasis kompetensi dan kewirausahaan.\n2. Mengembangkan penelitian di bidang manajemen keuangan, pemasaran, SDM, dan operasional yang relevan dengan dunia usaha.\n3. Melaksanakan pengabdian kepada masyarakat dalam pemberdayaan UMKM dan tata kelola organisasi.','Pengantar Bisnis & Manajemen, Manajemen Keuangan, Manajemen Pemasaran, Manajemen SDM, Manajemen Operasional, Studi Kelayakan Bisnis, Kewirausahaan, Manajemen Strategik, Magang / KKN, Skripsi','Manajer / Staf Manajerial Perusahaan Swasta & BUMN, Analis Keuangan dan Investasi, Spesialis SDM (HRD), Konsultan Bisnis, Wirausahawan','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(44,1,'Akuntansi','S1','Unggul','S.Ak.','Rp 3.000.000','Program studi di bawah Fakultas Ekonomi dan Bisnis (FEB) UNTAD yang mencetak akuntan profesional yang adaptif terhadap transformasi digital, pelaporan keuangan berkelanjutan, serta tata kelola perusahaan (corporate governance).','VISI KEILMUAN:\n\"Menjadi program studi akuntansi yang unggul dan berdaya saing dalam pelaporan keuangan berkelanjutan, tata kelola perusahaan, dan transformasi digital berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan akuntansi yang bermutu berbasis etika profesi, standar akuntansi, dan teknologi informasi.\n2. Mengembangkan penelitian di bidang akuntansi keuangan, auditing, perpajakan, sistem informasi akuntansi, dan akuntansi sektor publik.\n3. Melaksanakan pengabdian kepada masyarakat dalam peningkatan tata kelola keuangan organisasi dan UMKM.','Akuntansi Keuangan Menengah & Lanjutan, Akuntansi Biaya & Manajemen, Perpajakan, Auditing (Pengauditan), Sistem Informasi Akuntansi, Akuntansi Sektor Publik, Akuntansi Forensik, Magang / KKN, Skripsi','Akuntan Publik / Auditor Eksternal (KAP), Auditor Internal Perusahaan & BUMN, Konsultan Pajak, Analis Keuangan, Pengelola Keuangan Instansi Pemerintah','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(45,1,'Manajemen PSDKU Kabupaten Morowali','S1','Baik','S.M.','Rp 1.600.000','Program Studi di Luar Kampus Utama (PSDKU) yang menyelenggarakan pendidikan S1 Manajemen di Kabupaten Morowali dengan mengacu pada induknya di FEB UNTAD Palu serta berfokus mendukung kebutuhan SDM manajemen industri dan kewirausahaan di kawasan industri Morowali.','VISI KEILMUAN:\n\"Menjadi program studi S1 Manajemen PSDKU Morowali yang unggul dalam menyiapkan SDM manajemen industri dan kewirausahaan yang berdaya saing dan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan manajemen yang bermutu dan relevan dengan kebutuhan industri serta pembangunan daerah Morowali.\n2. Mengembangkan penelitian terapan di bidang manajemen industri, kewirausahaan, dan pemberdayaan ekonomi lokal.\n3. Melaksanakan pengabdian kepada masyarakat untuk mendukung pertumbuhan UMKM dan tata kelola usaha di Morowali.','Pengantar Bisnis & Manajemen, Manajemen Keuangan, Manajemen Pemasaran, Manajemen SDM, Manajemen Operasional Industri, Kewirausahaan, Studi Kelayakan Bisnis, Magang / KKN, Skripsi','Staf Manajemen & Administrasi Kawasan Industri Pertambangan / Pengolahan Mineral, Pengelola UMKM Lokal, Aparatur Pemerintah Daerah','SNBP, SNBT, dan Seleksi Mandiri PSDKU UNTAD.',NULL,NULL),(46,1,'Manajemen PSDKU Kabupaten Tojo Una-Una','S1','Unggul','S.M.','Rp 1.600.000','Program Studi di Luar Kampus Utama (PSDKU) yang berlokasi di Kabupaten Tojo Una-Una dengan struktur kurikulum mengacu pada induk FEB UNTAD. Ditekankan pada pengembangan kewirausahaan, manajemen pariwisata bahari (kawasan Kepulauan Togean), dan tata kelola bisnis daerah.','VISI KEILMUAN:\n\"Menjadi program studi S1 Manajemen PSDKU Tojo Una-Una yang unggul dalam kewirausahaan, manajemen pariwisata bahari, dan tata kelola bisnis berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan manajemen yang bermutu dengan keunggulan pada pariwisata bahari dan kewirausahaan daerah.\n2. Mengembangkan penelitian di bidang manajemen pariwisata, ekonomi kepulauan, dan pengembangan usaha daerah.\n3. Melaksanakan pengabdian kepada masyarakat untuk memajukan pariwisata dan ekonomi lokal Tojo Una-Una.','Pengantar Bisnis & Manajemen, Manajemen Keuangan, Manajemen Pemasaran Pariwisata, Manajemen SDM, Manajemen Operasional, Kewirausahaan, Pengelolaan Usaha Kecil & Pariwisata Bahari, Magang / KKN, Skripsi','Manajer Usaha Pariwisata & Perhotelan, Staf Perbankan / BUMN Daerah, Aparatur Pemerintah Kabupaten, Wirausahawan Lokal','SNBP, SNBT, dan Seleksi Mandiri PSDKU UNTAD.',NULL,NULL),(47,1,'Magister Manajemen','S2','Unggul','M.M.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi magister di bawah Fakultas Ekonomi dan Bisnis (FEB) UNTAD yang berfokus pada pengembangan kompetensi kepemimpinan strategis, pengambilan keputusan manajerial, dan inovasi bisnis bagi praktisi maupun akademisi dengan pilihan konsentrasi Manajemen Keuangan, Pemasaran, SDM, dan Manajemen Publik/Sektor Jasa.','VISI KEILMUAN:\n\"Menjadi program studi magister manajemen yang unggul dan berdaya saing dalam kepemimpinan strategis, kewirausahaan, dan tata kelola bisnis berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister manajemen yang bermutu dan adaptif terhadap dinamika bisnis serta teknologi.\n2. Mengembangkan penelitian inovatif di bidang manajemen keuangan, pemasaran, SDM, dan manajemen sektor publik/jasa.\n3. Melaksanakan pengabdian kepada masyarakat melalui konsultasi manajerial dan penguatan daya saing organisasi.','Filsafat Ilmu & Metodologi Penelitian Bisnis, Ekonomi Manajerial, Manajemen Strategik Lanjut, Manajemen Keuangan Korporat, Manajemen Pemasaran Strategik, Manajemen Perubahan & Kepemimpinan, Publikasi Karya Ilmiah, Tesis','Manajer Senior / Eksekutif Perusahaan Swasta & BUMN, Konsultan Bisnis dan Manajemen, Dosen Ilmu Manajemen, Pimpinan Unit Kerja Instansi Pemerintah','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(48,1,'Magister Akuntansi','S2','Unggul','M.Ak.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi magister yang dikelola oleh FEB dan Pascasarjana UNTAD dengan pilihan peminatan Akuntansi Sektor Publik, Akuntansi Keuangan & Pasar Modal, Audit, serta Perpajakan untuk menghasilkan akademisi dan praktisi akuntansi berintegritas.','VISI KEILMUAN:\n\"Menjadi program studi magister akuntansi yang unggul dan berdaya saing dalam pelaporan keuangan, audit, akuntansi sektor publik, dan tata kelola korporat berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister akuntansi yang bermutu berbasis standar profesi, etika, dan riset.\n2. Mengembangkan penelitian di bidang akuntansi keuangan, akuntansi sektor publik, audit, perpajakan, dan tata kelola perusahaan.\n3. Melaksanakan pengabdian kepada masyarakat untuk memperkuat akuntabilitas keuangan dan tata kelola organisasi.','Filsafat Ilmu & Metodologi Penelitian Akuntansi, Teori Akuntansi Lanjut, Akuntansi Sektor Publik Lanjut, Audit & Asurans Lanjut, Manajemen Perpajakan, Sistem Informasi & Tata Kelola Korporat (Good Corporate Governance), Publikasi Jurnal Ilmiah, Tesis','Dosen Ilmu Akuntansi, Auditor Senior (BPK / BPKP / Inspektorat / KAP), Manajer Keuangan / Akuntansi Perusahaan, Analis Anggaran Instansi Pemerintah, Konsultan Pajak dan Tata Kelola Keuangan','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(49,1,'Magister Ekonomi','S2','Baik Sekali','M.E.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi magister di bawah FEB dan Pascasarjana UNTAD yang berfokus pada analisis ekonomi pembangunan, ekonomi publik dan keuangan daerah, ekonomi moneter, serta perencanaan pembangunan wilayah berbasis sumber daya alam di Sulawesi Tengah dan kawasan Timur Indonesia.','VISI KEILMUAN:\n\"Menjadi program studi magister ekonomi yang unggul dan berdaya saing dalam analisis ekonomi pembangunan, keuangan daerah, dan perencanaan wilayah berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister ekonomi yang bermutu dengan penguasaan teori ekonomi lanjut dan metode kuantitatif/ekonometrika.\n2. Mengembangkan penelitian di bidang ekonomi pembangunan, kebijakan fiskal/moneter, dan ekonomi sumber daya wilayah.\n3. Melaksanakan pengabdian kepada masyarakat untuk mendukung perumusan kebijakan ekonomi daerah.','Filsafat Ilmu & Metodologi Penelitian Ekonomi, Teori Ekonomi Mikro & Makro Lanjut, Ekonometrika Lanjut, Ekonomi Pembangunan & Perencanaan Regional, Ekonomi Publik & Kebijakan Fiskal, Publikasi Karya Ilmiah, Tesis','Dosen Ilmu Ekonomi, Perencana Pembangunan & Analis Kebijakan Ekonomi (Bappenas / Bappeda / Kemenkeu), Peneliti Ekonomi, Analis Riset Lembaga Perbankan dan Keuangan','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(50,1,'Doktor Ilmu Ekonomi','S3','Baik Sekali','Dr.','Rp 12.000.000 (Matrikulasi Rp 1.000.000)','Program studi doktoral di bawah Fakultas Ekonomi dan Bisnis (FEB) dan Pascasarjana UNTAD yang memiliki 3 pilihan konsentrasi utama (Ilmu Ekonomi Pembangunan, Ilmu Manajemen, dan Ilmu Akuntansi), menampung lulusan S2 dari seluruh jurusan di FEB secara linier dengan wawasan pembangunan berkelanjutan.','VISI KEILMUAN:\n\"Menjadi program studi doktor ilmu ekonomi yang unggul dan berdaya saing internasional dalam pengembangan teori dan riset ekonomi, manajemen, serta akuntansi berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan doktoral ilmu ekonomi yang bermutu dan bertaraf internasional.\n2. Mengembangkan penelitian mendalam dan inovatif di bidang ekonomi pembangunan, manajemen, dan akuntansi yang dipublikasikan pada jurnal bereputasi.\n3. Melaksanakan pengabdian kepada masyarakat melalui diseminasi kebijakan strategis dan tata kelola berkelanjutan.','Filsafat Ilmu & Metodologi Penelitian Lanjut Ekonomi/Bisnis, Kajian Teori Ekonomi/Manajemen/Akuntansi Mutakhir, Publikasi Jurnal Internasional Bereputasi, Ujian Kualifikasi, Proposal Disertasi, Seminar Hasil, Ujian Tertutup dan Terbuka Disertasi','Dosen / Guru Besar Bidang Ekonomi, Manajemen, dan Akuntansi, Peneliti Utama Kebijakan Ekonomi dan Bisnis, Konsultan Strategis Pemerintahan maupun Korporasi','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(51,2,'Ilmu Hukum','S1','Baik Sekali','S.H.','Rp 4.000.000','Program studi di bawah Fakultas Hukum (FH) UNTAD yang mencakup 4 bidang kajian utama (Hukum Perdata, Hukum Pidana, Hukum Tata Negara & Hukum Administrasi Negara, serta Hukum Internasional) dengan beban studi 144?146 SKS berbasis OBE.','VISI KEILMUAN:\n\"Mewujudkan Fakultas Hukum yang Unggul dan Berdampak Terhadap Pengelolaan Lingkungan Berkelanjutan dan Pengembangan IPTEKS Secara Global.\"\n\nMISI:\n1. Menyelenggarakan pendidikan tinggi hukum berbasis OBE yang bermutu, berintegritas, dan berwawasan lingkungan berkelanjutan.\n2. Mengembangkan penelitian hukum yang responsif terhadap perkembangan IPTEKS dan pengelolaan lingkungan berkelanjutan.\n3. Melaksanakan pengabdian kepada masyarakat melalui edukasi hukum, advokasi, dan pemberdayaan masyarakat.','Pengantar Ilmu Hukum, Pengantar Hukum Indonesia, Hukum Perdata, Hukum Pidana, Hukum Tata Negara, Hukum Administrasi Negara, Hukum Internasional, Hukum Adat & Hukum Islam, Hukum Acara & Praktik Peradilan (Perdata, Pidana, TUN), Hukum Lingkungan, Magang / KKN, Skripsi','Hakim, Jaksa, Advokat / Pengacara, Notaris / PPAT, Staf Legal Perusahaan / BUMN, Legal Drafter Instansi Pemerintah / DPRD, Diplomat','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(52,2,'Ilmu Hukum (Magister Hukum)','S2','Baik','M.H.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi magister di bawah Fakultas Hukum (FH) UNTAD dengan beban studi 54 SKS (4 semester) dan 4 pilihan konsentrasi: Hukum Pidana, Hukum Bisnis, Hukum Tata Negara / Hukum Administrasi Negara (HTN/HAN), serta Hukum Lingkungan.','VISI KEILMUAN:\n\"Menjadi Pusat Pengembangan Ilmu Hukum yang Unggul dan Berdampak dalam Mengintegrasikan Aspek Lingkungan Berkelanjutan serta Responsif terhadap Perkembangan IPTEKS Global pada Tahun 2045.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister hukum yang unggul dalam mengintegrasikan aspek lingkungan berkelanjutan dan IPTEKS.\n2. Mengembangkan penelitian hukum lanjut di bidang pidana, bisnis, HTN/HAN, dan hukum lingkungan yang berdampak.\n3. Melaksanakan pengabdian kepada masyarakat untuk memperkuat kesadaran hukum dan tata kelola berkelanjutan.','Mata Kuliah Wajib Prodi (19 SKS), Mata Kuliah Wajib Konsentrasi (17 SKS), Mata Kuliah Pilihan Konsentrasi (4 SKS), Seminar Proposal (3 SKS), Seminar Hasil Penelitian (3 SKS), Tesis (8 SKS)','Dosen Ilmu Hukum, Konsultan Hukum Bisnis dan Lingkungan, Penegak Hukum (Hakim / Jaksa / Advokat), Analis Kebijakan Hukum Instansi Pemerintah / DPRD, Peneliti Hukum','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(53,9,'Agroteknologi','S1','Unggul','S.P.','Rp 3.000.000','Program studi induk di bawah Fakultas Pertanian (FAPERTA) UNTAD yang berfokus pada teknologi budidaya tanaman berkelanjutan, pemuliaan tanaman, ilmu tanah, kesuburan lahan, serta pengelolaan sumber daya pertanian tropis berwawasan lingkungan hidup.','VISI KEILMUAN:\n\"Menjadi program studi agroteknologi yang unggul dan berdaya saing dalam pengembangan teknologi budidaya dan pengelolaan sumber daya pertanian tropis berwawasan lingkungan hidup.\"\n\nMISI:\n1. Menyelenggarakan pendidikan agroteknologi yang bermutu dan adaptif terhadap perkembangan IPTEKS pertanian tropis.\n2. Mengembangkan penelitian inovatif di bidang agronomi, ilmu tanah, pemuliaan tanaman, dan perlindungan tanaman berkelanjutan.\n3. Melaksanakan pengabdian kepada masyarakat dalam penerapan teknologi pertanian ramah lingkungan dan peningkatan produktivitas lahan.','Dasar-Dasar Agronomi, Ilmu Tanah & Kesuburan Tanah, Genetika & Pemuliaan Tanaman, Fisiologi Tumbuhan, Dasar-Dasar Perlindungan Tanaman, Teknologi Produksi Tanaman Pangan/Hortikultura/Perkebunan, Magang / KKN, Skripsi','Manajer / Asisten Kebun Perusahaan Perkebunan, Penyuluh Pertanian Lapangan (PPL / ASN), Produsen / Penangkar Benih, Peneliti Pertanian, Wirausahawan Agroteknologi','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(54,9,'Agribisnis','S1','Unggul','S.P.','Rp 3.000.000','Program studi di bawah Jurusan Sosial Ekonomi Pertanian FAPERTA UNTAD yang memadukan ilmu pertanian dengan manajemen bisnis, rantai pasok, pemasaran komoditas pertanian, serta pemberdayaan ekonomi masyarakat tani.','VISI KEILMUAN:\n\"Menjadi program studi agribisnis yang unggul dan berdaya saing dalam pengembangan sistem dan bisnis pertanian berkelanjutan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan agribisnis yang bermutu untuk menghasilkan manajer, analis, dan wirausahawan pertanian yang profesional.\n2. Mengembangkan penelitian di bidang manajemen agribisnis, rantai pasok, pemasaran komoditas, dan pemberdayaan kelembagaan petani.\n3. Melaksanakan pengabdian kepada masyarakat dalam penguatan usaha tani dan ketahanan pangan daerah.','Pengantar Ilmu Ekonomi Pertanian, Manajemen Agribisnis, Pemasaran & Rantai Pasok Agribisnis, Studi Kelayakan Bisnis Pertanian, Koperasi & Kelembagaan Tani, Kewirausahaan Agribisnis, Magang / KKN, Skripsi','Manajer / Analis Bisnis Perusahaan Agribisnis & Perbankan, Konsultan Pengembangan Usaha Tani, Aparatur Dinas Pertanian / Ketahanan Pangan, Agripreneur','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(55,9,'Proteksi Tanaman','S1','Baik','S.P.','Rp 3.000.000','Program studi di bawah FAPERTA UNTAD yang fokus mengkaji perlindungan tanaman dari organisme pengganggu tumbuhan (OPT), pengendalian hama terpadu (PHT), penyakit tumbuhan, serta karantina pertanian yang ramah lingkungan.','VISI KEILMUAN:\n\"Menjadi program studi proteksi tanaman yang unggul dalam pengendalian organisme pengganggu tumbuhan dan perlindungan tanaman berkelanjutan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan proteksi tanaman yang bermutu berbasis riset dan praktik lapangan.\n2. Mengembangkan penelitian di bidang entomologi, fitopatologi, gulma, pengendalian hama terpadu, dan karantina tumbuhan.\n3. Melaksanakan pengabdian kepada masyarakat dalam mitigasi serangan OPT dan penerapan pestisida ramah lingkungan.','Entomologi Pertanian, Fitopatologi (Ilmu Penyakit Tumbuhan), Ilmu Gulma, Pengendalian Hama Terpadu (PHT), Toksikologi Pestisida & Pestisida Nabati, Karantina Tumbuhan, Praktikum Laboratorium/Lapangan, KKN, Skripsi','Petugas Pengendali Organisme Pengganggu Tumbuhan (POPT / ASN), Petugas Badan Karantina Indonesia, Spesialis Perlindungan Tanaman Perusahaan Perkebunan & Agrokimia, Peneliti OPT','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(56,9,'Agroteknologi PSDKU Kabupaten Morowali','S1','B','S.P.','Rp 1.750.000','Program Studi di Luar Kampus Utama (PSDKU) di Kabupaten Morowali yang menginduk pada S1 Agroteknologi Palu dengan penekanan pada pertanian lahan kering, reklamasi atau penghijauan lahan pascatambang, dan pengembangan komoditas perkebunan lokal Morowali.','VISI KEILMUAN:\n\"Menjadi program studi S1 Agroteknologi PSDKU Morowali yang unggul dalam reklamasi lahan, budidaya tanaman lahan kering, dan pertanian berkelanjutan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan agroteknologi yang bermutu dan relevan dengan kebutuhan reklamasi lahan serta pertanian di Morowali.\n2. Mengembangkan penelitian terapan di bidang reklamasi pascatambang, kesuburan lahan kering, dan budidaya komoditas lokal.\n3. Melaksanakan pengabdian kepada masyarakat untuk pemulihan lingkungan dan peningkatan produktivitas pertanian Morowali.','Dasar-Dasar Agronomi, Ilmu Tanah & Kesuburan Tanah, Teknologi Reklamasi & Konservasi Lahan, Budidaya Tanaman Perkebunan & Lahan Kering, Perlindungan Tanaman, Magang / KKN, Skripsi','Staf Reklamasi Lingkungan & Penghijauan Perusahaan Pertambangan, Asisten Perkebunan, Penyuluh Pertanian Daerah, Wirausahawan Pertanian','SNBP, SNBT, dan Seleksi Mandiri PSDKU UNTAD.',NULL,NULL),(57,9,'Agroteknologi PSDKU Kabupaten Tojo Una-Una','S1','Baik','S.P.','Rp 1.750.000','Program Studi di Luar Kampus Utama (PSDKU) yang berlokasi di Kampus PSDKU Malotong, Ampana Kota, Kabupaten Tojo Una-Una, dengan struktur kurikulum yang disesuaikan dengan potensi komoditas unggulan pesisir dan kepulauan (kelapa, kakao, cengkeh, dan hortikultura).','VISI KEILMUAN:\n\"Menjadi program studi S1 Agroteknologi PSDKU Tojo Una-Una yang unggul dalam budidaya tanaman pesisir dan kepulauan yang berkelanjutan dan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan agroteknologi yang bermutu dengan keunggulan pada komoditas pesisir dan kepulauan Tojo Una-Una.\n2. Mengembangkan penelitian terapan di bidang budidaya kelapa, kakao, cengkeh, hortikultura, dan agroekoteknologi kepulauan.\n3. Melaksanakan pengabdian kepada masyarakat dalam pemberdayaan petani dan pengembangan agribisnis lokal.','Dasar-Dasar Agronomi, Ilmu Tanah & Kesuburan Tanah, Budidaya Tanaman Perkebunan Pesisir & Kepulauan (Kelapa, Kakao, Cengkeh), Budidaya Hortikultura, Perlindungan Tanaman, Magang / KKN, Skripsi','Penyuluh Pertanian Daerah, Pengelola Perkebunan Rakyat, Staf Dinas Pertanian / Ketahanan Pangan Kabupaten, Pelaku Usaha Agribisnis Lokal','SNBP, SNBT, dan Seleksi Mandiri PSDKU UNTAD.',NULL,NULL),(58,9,'Magister Agribisnis','S2','Unggul','M.Agr.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Berdiri sejak tahun 2014 di bawah pengelolaan FAPERTA dan Pascasarjana UNTAD. Program studi ini diarahkan untuk mencetak akademisi, birokrat, dan praktisi agribisnis yang memiliki kompetensi manajerial andal dalam pengelolaan rantai nilai komoditas pertanian berkelanjutan.','VISI KEILMUAN:\n\"Menjadi program studi magister agribisnis yang unggul dan berdaya saing dalam pengelolaan rantai nilai dan bisnis pertanian berkelanjutan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister agribisnis yang bermutu untuk menghasilkan akademisi, birokrat, dan praktisi yang profesional.\n2. Mengembangkan penelitian di bidang manajemen agribisnis, rantai pasok, kebijakan pertanian, dan kelembagaan petani.\n3. Melaksanakan pengabdian kepada masyarakat dalam penguatan sistem agribisnis dan ketahanan pangan daerah.','Filsafat Ilmu & Metodologi Penelitian Agribisnis, Ekonomi Manajerial & Kebijakan Agribisnis, Manajemen Pemasaran & Rantai Pasok Strategik, Analisis Kuantitatif & Ekonometrika Agribisnis, Pengembangan Kelembagaan & Pemberdayaan Masyarakat Tani, Publikasi Karya Ilmiah, Tesis','Dosen Ilmu Agribisnis / Sosial Ekonomi Pertanian, Manajer Senior Perusahaan Agribisnis & Perkebunan, Analis Kebijakan Ketahanan Pangan (Kementan / Bappeda), Konsultan Pengembangan Bisnis Pertanian','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(59,9,'Magister Ilmu Pertanian','S2','Unggul','M.P.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Berdiri sejak tahun 2014 di bawah FAPERTA dan Pascasarjana UNTAD dengan pilihan konsentrasi Ilmu Tanaman, Ilmu Tanah, dan Perlindungan Tanaman. Berfokus pada pengembangan riset dan teknologi pertanian tropis berkelanjutan yang berwawasan lingkungan alami.','VISI KEILMUAN:\n\"Menjadi program studi magister ilmu pertanian yang unggul dalam riset dan teknologi pertanian tropis berkelanjutan yang berwawasan lingkungan alami.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister ilmu pertanian yang bermutu dengan konsentrasi Ilmu Tanaman, Ilmu Tanah, dan Perlindungan Tanaman.\n2. Mengembangkan penelitian inovatif di bidang budidaya tropis, kesuburan tanah, dan perlindungan tanaman berkelanjutan.\n3. Melaksanakan pengabdian kepada masyarakat melalui diseminasi teknologi pertanian ramah lingkungan.','Filsafat Ilmu & Metodologi Penelitian, Mata Kuliah Wajib Program Studi, Konsentrasi Ilmu Tanaman / Ilmu Tanah / Perlindungan Tanaman (Agronomi Lanjut, Kesuburan Tanah Lanjut, PHT Lanjut), Publikasi Ilmiah, Tesis','Dosen Ilmu Pertanian / Agroteknologi / Ilmu Tanah / Proteksi Tanaman, Peneliti (BRIN / Balai Penelitian Pertanian), Manajer R&D Perusahaan Perkebunan & Perbenihan, Konsultan Pertanian Berkelanjutan','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(60,9,'Doktor Ilmu Pertanian','S3','Baik Sekali','Dr.','Rp 12.000.000 (Matrikulasi Rp 1.000.000)','Berdiri sejak 30 Desember 2016 dan berlokasi di Gedung A Kampus Pascasarjana UNTAD Palu. Memadukan pendekatan teknologi dan sosial ekonomi pertanian berkelanjutan dengan pilihan konsentrasi keilmuan Ilmu Tanaman, Ilmu Tanah, Perlindungan Tanaman, serta Sosial Ekonomi Pertanian / Agribisnis.','VISI KEILMUAN:\n\"Menjadi program studi doktor ilmu pertanian yang unggul dan berdaya saing internasional dalam pengembangan riset teknologi dan sosial ekonomi pertanian berkelanjutan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan doktoral ilmu pertanian yang bermutu dan bertaraf internasional.\n2. Mengembangkan penelitian mendalam dan inovatif di bidang ilmu tanaman, ilmu tanah, perlindungan tanaman, dan sosial ekonomi pertanian/agribisnis.\n3. Melaksanakan pengabdian kepada masyarakat melalui diseminasi riset strategis dan kebijakan ketahanan pangan berkelanjutan.','Matrikulasi (Bahasa Inggris, Statistika, Metode & Teknik Penulisan Artikel, Pertanian Berkelanjutan), Mata Kuliah Wajib & Konsentrasi Doktoral, Publikasi Jurnal Internasional Bereputasi, Ujian Kualifikasi, Proposal Disertasi, Seminar Hasil, Ujian Tertutup dan Terbuka Disertasi','Dosen / Guru Besar Bidang Pertanian, Agroteknologi, dan Agribisnis, Peneliti Utama (BRIN / Balai Penelitian Pertanian), Konsultan Kebijakan Ketahanan Pangan dan Lingkungan','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(61,11,'Teknologi Rekayasa Konstruksi Jalan dan Jembatan','D4','Unggul','S.Tr.T.','Rp 3.000.000','Transformasi dari D3 Teknik Sipil di bawah Jurusan Teknik Sipil FATEK UNTAD yang berfokus pada rekayasa pelaksanaan, pengawasan, serta pemeliharaan konstruksi jalan raya dan jembatan dengan porsi praktikum lapangan dan laboratorium yang dominan.','VISI KEILMUAN:\n\"Menjadi program studi sarjana terapan teknologi rekayasa konstruksi jalan dan jembatan yang unggul dan berdaya saing dalam infrastruktur berkelanjutan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan vokasi konstruksi jalan dan jembatan berbasis praktik lapangan dan laboratorium yang bermutu.\n2. Mengembangkan penelitian terapan di bidang perkerasan jalan, rekayasa jembatan, material konstruksi, dan manajemen proyek.\n3. Melaksanakan pengabdian kepada masyarakat untuk mendukung pembangunan infrastruktur wilayah yang aman dan berkelanjutan.','Gambar Teknik & CAD Sipil, Mekanika Tanah & Rekayasa Pondasi, Teknologi Bahan Konstruksi (Beton & Aspal), Perancangan Perkerasan Jalan Raya, Konstruksi Jembatan, Manajemen Proyek & Estimasi Biaya Konstruksi (RAB), Keselamatan dan Kesehatan Kerja (K3) Konstruksi, Praktik Kerja Lapangan (PKL), Tugas Akhir Terapan','Site Engineer / Pelaksana Lapangan, Pengawas Proyek Konstruksi Jalan & Jembatan (BUMN / Swasta), Staf Teknis Kementerian PUPR / Dinas PU, Konsultan Perencana & Pengawas Infrastruktur','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(62,11,'Teknologi Rekayasa Manufaktur','D4','Baik Sekali','S.Tr.T.','Rp 3.000.000','Transformasi dari D3 Teknik Mesin di bawah Jurusan Teknik Mesin FATEK UNTAD yang berfokus pada proses produksi manufaktur, permesinan presisi (CNC), perancangan komponen mekanik, serta pemeliharaan mesin industri termasuk untuk kebutuhan industri pengolahan mineral di Sulawesi Tengah.','VISI KEILMUAN:\n\"Menjadi program studi sarjana terapan teknologi rekayasa manufaktur yang unggul dan berdaya saing dalam proses produksi presisi dan perawatan mesin industri berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan vokasi manufaktur berbasis industri dan praktik bengkel/laboratorium yang bermutu.\n2. Mengembangkan penelitian terapan di bidang permesinan CNC, CAD/CAM, fabrikasi logam, metrologi, dan perawatan mesin.\n3. Melaksanakan pengabdian kepada masyarakat untuk mendukung penguatan SDM industri dan bengkel lokal.','Gambar Mesin & CAD/CAM, Proses Manufaktur & Pemesinan CNC, Teknologi Pengelasan & Fabrikasi Logam, Metrologi Industri & Kontrol Kualitas, Pneumatik & Hidrolik Industri, Manajemen Perawatan Mesin Industri, K3 Industri, Magang Industri, Tugas Akhir Terapan','Manufacturing Engineer, Production Supervisor, Spesialis Pemrograman CNC & CAD/CAM, Teknisi Pemeliharaan Mesin Pabrik (Kawasan Industri / Pertambangan), Wirausahawan Bengkel Manufaktur','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(63,11,'Teknologi Rekayasa Instalasi Listrik','D4','Baik Sekali','S.Tr.T.','Rp 3.000.000','Transformasi dari D3 Teknik Listrik di bawah Jurusan Teknik Elektro FATEK UNTAD yang berfokus pada perancangan, pemasangan, pengujian, serta pemeliharaan sistem instalasi kelistrikan bangunan industri, pembangkitan, dan otomasi kelistrikan.','VISI KEILMUAN:\n\"Menjadi program studi sarjana terapan teknologi rekayasa instalasi listrik yang unggul dan berdaya saing dalam sistem kelistrikan industri, otomasi, dan energi berkelanjutan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan vokasi ketenagalistrikan berbasis praktik laboratorium dan industri yang bermutu.\n2. Mengembangkan penelitian terapan di bidang instalasi listrik, sistem proteksi, otomasi industri (PLC), dan energi baru terbarukan.\n3. Melaksanakan pengabdian kepada masyarakat dalam keselamatan ketenagalistrikan dan pemanfaatan energi terbarukan.','Rangkaian Listrik & Pengukuran, Instalasi Listrik Domestik & Industri, Mesin-Mesin Listrik & Transformator, Sistem Proteksi & Gardu Distribusi, Otomasi Industri & PLC (Programmable Logic Controller), Energi Baru Terbarukan (PLTS), K3 Ketenagalistrikan, Magang Industri, Tugas Akhir Terapan','Electrical Engineer Instalasi & Pemeliharaan Pabrik/Gedung, Teknisi Kelistrikan PLN & Pembangkit Listrik, Spesialis Otomasi Industri (PLC), Inspektur K3 Listrik, Kontraktor Instalasi Listrik','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(64,11,'Teknik Sipil','S1','Unggul','S.T.','Rp 4.000.000','Program studi perintis di Fakultas Teknik (FATEK) UNTAD yang berfokus pada perancangan, pembangunan, dan pemeliharaan infrastruktur bangunan gedung, jembatan, jalan raya, sumber daya air, serta rekayasa kegempaan dan geoteknik berwawasan lingkungan.','VISI KEILMUAN:\n\"Menjadi program studi teknik sipil yang unggul dan berdaya saing dalam rekayasa infrastruktur tahan gempa dan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan teknik sipil yang bermutu dan relevan dengan kebutuhan rekayasa infrastruktur serta kebencanaan.\n2. Mengembangkan penelitian inovatif di bidang struktur, geoteknik, keairan, transportasi, dan manajemen konstruksi.\n3. Melaksanakan pengabdian kepada masyarakat melalui penerapan teknologi konstruksi yang aman dan berkelanjutan.','Mekanika Bahan, Analisis Struktur, Rekayasa Pondasi & Geoteknik, Hidrolika & Rekayasa Sumber Daya Air, Rekayasa Transportasi, Manajemen Konstruksi, Rekayasa Gempa, Kerja Praktik, Skripsi','Konsultan Perencana dan Pengawas Konstruksi, Project Manager / Site Engineer (BUMN / Swasta), Aparatur Kementerian PUPR / Dinas Pekerjaan Umum, Peneliti Infrastruktur','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(65,11,'Teknik Lingkungan','S1','Baik Sekali','S.T.','Rp 3.000.000','Program studi di bawah Fakultas Teknik (FATEK) UNTAD yang berfokus pada rekayasa pengelolaan kualitas air bersih, pengolahan air limbah (IPAL), pengelolaan persampahan dan limbah B3, pengendalian pencemaran udara, serta analisis dampak lingkungan (AMDAL).','VISI KEILMUAN:\n\"Menjadi program studi teknik lingkungan yang unggul dan berdaya saing dalam pengelolaan lingkungan berkelanjutan dan pengendalian pencemaran berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan teknik lingkungan yang bermutu berbasis riset dan praktik rekayasa lingkungan.\n2. Mengembangkan penelitian di bidang pengolahan air dan limbah, persampahan/B3, pencemaran udara, dan AMDAL.\n3. Melaksanakan pengabdian kepada masyarakat dalam pengelolaan lingkungan dan sanitasi berkelanjutan.','Kimia & Mikrobiologi Lingkungan, Mekanika Fluida, Sistem Penyediaan Air Minum, Pengolahan Air Limbah, Pengelolaan Sampah & Limbah B3, AMDAL & Audit Lingkungan, Kerja Praktik, Skripsi','Environmental Engineer (Pertambangan / Industri Pengolahan / Manufaktur), Konsultan AMDAL, Aparatur Dinas Lingkungan Hidup / KLHK, Pengelola PDAM','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(66,11,'Perencanaan Wilayah dan Kota','S1','Baik Sekali','S.P.W.K.','Rp 3.000.000','Program studi di bawah Fakultas Teknik (FATEK) UNTAD yang mengkaji tata ruang kota dan wilayah, perencanaan infrastruktur kawasan, sistem informasi geografis (SIG) perkotaan, serta perencanaan kota tangguh bencana dan berwawasan lingkungan.','VISI KEILMUAN:\n\"Menjadi program studi perencanaan wilayah dan kota yang unggul dalam perencanaan tata ruang berkelanjutan dan tangguh bencana berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan PWK yang bermutu berbasis studio perencanaan, SIG, dan analisis spasial.\n2. Mengembangkan penelitian di bidang tata ruang, infrastruktur kawasan, pengembangan wilayah, dan mitigasi bencana.\n3. Melaksanakan pengabdian kepada masyarakat dalam penyusunan rencana tata ruang dan pengembangan kawasan.','Pengantar Perencanaan Wilayah & Kota, Studio Perencanaan Tapak/Kota/Wilayah, Perencanaan Transportasi & Infrastruktur Kota, SIG & Pemetaan Tata Ruang, Hukum & Administrasi Perencanaan, Perencanaan Kebencanaan, Kerja Praktik, Skripsi','Urban & Regional Planner (Konsultan Perencanaan), Aparatur Pemerintah (Bappeda / Kementerian ATR/BPN / Dinas Tata Ruang), Analis Properti & Kawasan Industri, Peneliti Pengembangan Wilayah','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(67,11,'Teknik Mesin','S1','Baik Sekali','S.T.','Rp 3.000.000','Program studi di bawah Fakultas Teknik (FATEK) UNTAD yang mempelajari prinsip-prinsip fisika dan rekayasa untuk perancangan, analisis, manufaktur, serta pemeliharaan sistem mekanik, konversi energi, dan material teknik.','VISI KEILMUAN:\n\"Menjadi program studi teknik mesin yang unggul dan berdaya saing dalam perancangan mekanik, manufaktur, dan konversi energi berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan teknik mesin yang bermutu berbasis teori, laboratorium, dan praktik industri.\n2. Mengembangkan penelitian di bidang konversi energi, material teknik, manufaktur, dan mekanika terapan.\n3. Melaksanakan pengabdian kepada masyarakat melalui penerapan teknologi tepat guna dan pemeliharaan mesin.','Statika Struktur & Mekanika Kekuatan Material, Termodinamika, Mekanika Fluida, Perpindahan Panas, Elemen Mesin, Metalurgi Fisik & Material Teknik, Proses Produksi & Manufaktur, Konversi Energi, Kerja Praktik, Skripsi','Mechanical Engineer (Industri Pengolahan Mineral/Smelter / Pertambangan / Pembangkit Listrik / Manufaktur / BUMN Energi), Konsultan Rekayasa Mekanikal','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(68,11,'Teknik Elektro','S1','Baik Sekali','S.T.','Rp 3.000.000','Program studi di bawah Fakultas Teknik (FATEK) UNTAD yang berfokus pada rekayasa sistem ketenagalistrikan (arus kuat), elektronika dan kendali otomasi industri, serta sistem telekomunikasi dan energi terbarukan.','VISI KEILMUAN:\n\"Menjadi program studi teknik elektro yang unggul dan berdaya saing dalam sistem tenaga listrik, kendali otomasi, telekomunikasi, dan energi terbarukan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan teknik elektro yang bermutu berbasis laboratorium dan kebutuhan industri.\n2. Mengembangkan penelitian di bidang tenaga listrik, elektronika/kendali otomasi, telekomunikasi, dan energi terbarukan.\n3. Melaksanakan pengabdian kepada masyarakat melalui penerapan teknologi elektro dan energi berkelanjutan.','Rangkaian Listrik, Medan Elektromagnetik, Elektronika Analog & Digital, Sistem Tenaga Listrik, Sistem Kendali & Otomasi Industri, Sistem Telekomunikasi, Mikroprosesor & Mikrokontroler, Energi Terbarukan, Kerja Praktik, Skripsi','Electrical & Instrumentation Engineer (PLN/IPP / Tambang & Smelter / Telekomunikasi), Spesialis Otomasi & Robotika Industri, Konsultan Ketenagalistrikan','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(69,11,'Teknik Informatika','S1','Baik Sekali','S.Kom.','Rp 4.000.000','Program studi di bawah Jurusan Teknologi Informasi FATEK UNTAD yang berfokus pada rekayasa perangkat lunak, kecerdasan buatan (artificial intelligence), jaringan komputer dan keamanan siber, serta komputasi cerdas.','VISI KEILMUAN:\n\"Menjadi program studi teknik informatika yang unggul dan berdaya saing dalam rekayasa perangkat lunak, komputasi cerdas, dan keamanan siber berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan teknik informatika yang bermutu dan adaptif terhadap perkembangan teknologi informasi.\n2. Mengembangkan penelitian inovatif di bidang perangkat lunak, AI/machine learning, jaringan/keamanan siber, dan sistem cerdas.\n3. Melaksanakan pengabdian kepada masyarakat melalui solusi digital dan literasi teknologi informasi.','Algoritma & Pemrograman, Struktur Data, Basis Data, Rekayasa Perangkat Lunak, Sistem Operasi, Jaringan Komputer & Keamanan Siber, Kecerdasan Buatan & Machine Learning, Pemrograman Web & Mobile, Kerja Praktik, Skripsi','Software Engineer / Developer, Data Scientist / AI Engineer, Cybersecurity Analyst, Network & Cloud Engineer, Konsultan Teknologi Informasi','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(70,11,'Teknik Geologi','S1','Baik Sekali','S.T.','Rp 3.000.000','Program studi di bawah Fakultas Teknik (FATEK) UNTAD yang mempelajari komposisi, struktur, sejarah bumi, eksplorasi sumber daya mineral dan energi (nikel, emas, migas, panas bumi), serta geologi tata lingkungan dan kebencanaan geologi di Sulawesi.','VISI KEILMUAN:\n\"Menjadi program studi teknik geologi yang unggul dalam eksplorasi sumber daya geologi dan mitigasi kebencanaan geologi berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan teknik geologi yang bermutu dengan penguatan pemetaan lapangan, petrologi, struktur, dan kebencanaan.\n2. Mengembangkan penelitian di bidang sumber daya mineral/energi, geologi teknik, hidrogeologi, dan kebencanaan geologi Sulawesi.\n3. Melaksanakan pengabdian kepada masyarakat dalam mitigasi bencana geologi dan pengelolaan sumber daya bumi berkelanjutan.','Geologi Fisik, Mineralogi & Petrologi, Geologi Struktur & Tektonik, Stratigrafi & Paleontologi, Pemetaan Geologi Lapangan, Eksplorasi Sumber Daya Mineral & Energi, Geologi Teknik & Kebencanaan, Kerja Praktik, Skripsi','Exploration & Mining Geologist (Pertambangan Nikel & Mineral), Geotechnical Engineer, Ahli Mitigasi Bencana Geologi (PVMBG / BMKG / BPBD), Konsultan Hidrogeologi','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(71,11,'Magister Teknik Sipil','S2','Unggul','M.T.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi magister di bawah Jurusan Teknik Sipil FATEK UNTAD yang memiliki 3 konsentrasi utama (Teknik Keairan, Manajemen dan Rekayasa Infrastruktur, serta Teknik Transportasi) untuk mendukung pembangunan infrastruktur tangguh bencana di Sulawesi Tengah.','VISI KEILMUAN:\n\"Menjadi program studi magister teknik sipil yang unggul dan berdaya saing dalam rekayasa infrastruktur tangguh bencana dan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister teknik sipil berbasis OBE yang bermutu pada bidang keairan, manajemen infrastruktur, dan transportasi.\n2. Mengembangkan penelitian inovatif dan aplikatif di bidang rekayasa sipil, mitigasi kebencanaan, dan infrastruktur berkelanjutan.\n3. Melaksanakan pengabdian kepada masyarakat melalui dukungan teknis dan perencanaan infrastruktur daerah.','Filsafat Ilmu & Metodologi Penelitian Teknik, Analisis Numerik & Pemodelan Teknik Sipil, Mata Kuliah Wajib Konsentrasi (Rekayasa Sumber Daya Air / Manajemen Proyek & Infrastruktur / Sistem Transportasi), Publikasi Karya Ilmiah, Seminar Proposal & Hasil, Tesis','Konsultan Perencana / Pengawas Infrastruktur Senior, Manajer Proyek Konstruksi Skala Besar (BUMN / Swasta), Aparatur Teknis Madya (Kementerian PUPR / Dinas PU), Dosen Teknik Sipil, Peneliti Kebencanaan & Infrastruktur','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD (termasuk skema fast-track S1 ke S2 bagi mahasiswa UNTAD).',NULL,NULL),(72,11,'Magister Teknologi Informasi','S2','Baik','M.Kom.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi magister di bawah Jurusan Teknologi Informasi FATEK UNTAD yang mulai membuka perkuliahan perdana pada semester gasal 2025/2026 dengan fokus pada Kecerdasan Buatan (Artificial Intelligence), Sistem Informasi Strategis, serta Inovasi Digital.','VISI KEILMUAN:\n\"Menjadi program studi magister teknologi informasi yang unggul dan adaptif dalam kecerdasan buatan, sistem informasi strategis, dan inovasi digital berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister teknologi informasi berbasis OBE yang bermutu dan relevan dengan transformasi digital.\n2. Mengembangkan penelitian di bidang AI/machine learning, arsitektur sistem informasi, keamanan siber, dan komputasi awan.\n3. Melaksanakan pengabdian kepada masyarakat dalam pemanfaatan teknologi informasi untuk tata kelola dan inovasi daerah.','Filsafat Ilmu & Metodologi Penelitian Teknologi Informasi, Kecerdasan Buatan & Pembelajaran Mesin Lanjut (Advanced AI & Machine Learning), Tata Kelola & Arsitektur Sistem Informasi Enterprise, Keamanan Siber & Komputasi Awan, Inovasi Digital & Transformasi Bisnis, Publikasi Ilmiah, Tesis','Dosen Ilmu Komputer / Teknik Informatika / Sistem Informasi, IT Architect / CTO, AI & Data Science Specialist, Konsultan Transformasi Digital, Peneliti Teknologi Informasi','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(73,11,'Teknik Sipil PSDKU Kabupaten Morowali','S1','Baik','S.T.','Rp 1.750.000','Program Studi di Luar Kampus Utama (PSDKU) di Kabupaten Morowali yang menyelenggarakan pendidikan S1 Teknik Sipil dengan menginduk langsung pada Jurusan Teknik Sipil FATEK UNTAD Palu, difokuskan untuk mendukung pembangunan infrastruktur kawasan industri dan pertambangan di Kabupaten Morowali.','VISI KEILMUAN:\n\"Menjadi program studi S1 teknik sipil PSDKU Morowali yang unggul dalam rekayasa infrastruktur industri dan wilayah yang tangguh serta berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan teknik sipil yang bermutu dan relevan dengan kebutuhan infrastruktur kawasan industri serta daerah Morowali.\n2. Mengembangkan penelitian terapan di bidang struktur, geoteknik, transportasi, dan manajemen konstruksi.\n3. Melaksanakan pengabdian kepada masyarakat melalui dukungan teknis pembangunan infrastruktur dan keselamatan konstruksi.','Mekanika Bahan, Analisis Struktur, Rekayasa Pondasi & Geoteknik, Hidrolika & Sumber Daya Air, Rekayasa Transportasi & Jalan Raya, Manajemen Konstruksi, Rekayasa Gempa, Kerja Praktik, Skripsi','Site Engineer / Pengawas Proyek Konstruksi Industri & Sipil (Kawasan Industri Morowali), Konsultan Perencana / Pengawas Infrastruktur, Aparatur Dinas PU Daerah, Kontraktor Sipil','SNBP, SNBT, dan Seleksi Mandiri PSDKU UNTAD.',NULL,NULL),(74,11,'Teknik Sipil PSDKU Kabupaten Tojo Una-Una','S1','Baik','S.T.','Rp 1.750.000','Program Studi di Luar Kampus Utama (PSDKU) yang berlokasi di Kampus PSDKU Malotong, Ampana Kota, Kabupaten Tojo Una-Una, menginduk pada FATEK UNTAD Palu dengan penekanan pada rekayasa infrastruktur wilayah pesisir, kepulauan, dan jalan/jembatan penghubung daerah.','VISI KEILMUAN:\n\"Menjadi program studi S1 teknik sipil PSDKU Tojo Una-Una yang unggul dalam rekayasa infrastruktur pesisir, kepulauan, dan wilayah yang berkelanjutan serta berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan teknik sipil yang bermutu dengan keunggulan pada infrastruktur pesisir, kepulauan, dan konektivitas daerah.\n2. Mengembangkan penelitian terapan di bidang rekayasa pantai, keairan, struktur, dan manajemen konstruksi daerah.\n3. Melaksanakan pengabdian kepada masyarakat untuk mendukung pembangunan infrastruktur dan mitigasi kebencanaan daerah.','Mekanika Teknik, Analisis Struktur Beton & Baja, Mekanika Tanah & Rekayasa Pondasi, Rekayasa Pantai & Sumber Daya Air, Rekayasa Transportasi, Manajemen Proyek & Estimasi Biaya, Kerja Praktik, Skripsi','Pelaksana / Pengawas Proyek Infrastruktur Daerah, Konsultan Teknik Sipil dan Pengairan, Aparatur Dinas PU / Bappeda Kabupaten, Wirausahawan Jasa Konstruksi','SNBP, SNBT, dan Seleksi Mandiri PSDKU UNTAD.',NULL,NULL),(75,11,'Doktor Teknik Sipil','S3','Baik','Dr.','Rp 12.000.000 (Matrikulasi Rp 1.000.000)','Program studi doktoral di bawah Fakultas Teknik (FATEK) dan Pascasarjana UNTAD yang didukung oleh tenaga pengajar bergelar Profesor dan Doktor di bidang keteknikan, dengan fokus riset pada rekayasa struktur dan kegempaan, geoteknik, sumber daya air, transportasi, serta manajemen infrastruktur tangguh bencana berwawasan lingkungan.','VISI KEILMUAN:\n\"Menjadi program studi doktor teknik sipil yang unggul dan berdaya saing internasional dalam pengembangan riset rekayasa infrastruktur tangguh bencana berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan doktoral teknik sipil yang bermutu dan bertaraf internasional.\n2. Mengembangkan penelitian mendalam dan inovatif di bidang struktur/kegempaan, geoteknik, keairan, transportasi, dan manajemen infrastruktur yang terpublikasi pada jurnal bereputasi.\n3. Melaksanakan pengabdian kepada masyarakat melalui diseminasi riset strategis dan rekayasa infrastruktur berkelanjutan.','Filsafat Ilmu & Metodologi Penelitian Lanjut Keteknikan, Kajian Mutakhir Rekayasa Infrastruktur & Kebencanaan, Publikasi Jurnal Internasional Bereputasi, Ujian Kualifikasi, Proposal Disertasi, Seminar Hasil, Ujian Tertutup dan Terbuka Disertasi','Dosen / Guru Besar Teknik Sipil, Peneliti Utama Rekayasa Infrastruktur & Mitigasi Bencana, Tenaga Ahli / Konsultan Senior Proyek Strategis Nasional','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(76,11,'Program Studi Program Profesi Insinyur','Profesi','Baik Sekali','Ir.','Mandiri Profesi (Sesuai Ketetapan Gelombang PSPPI)','Program studi profesi di bawah Fakultas Teknik (FATEK) UNTAD bekerja sama dengan Persatuan Insinyur Indonesia (PII) Wilayah Sulawesi Tengah berdasarkan UU Nomor 11 Tahun 2014 tentang Keinsinyuran, untuk mencetak insinyur profesional yang berintegritas dan menjamin keselamatan serta kemaslahatan masyarakat.','VISI KEILMUAN:\n\"Menjadi program studi program profesi insinyur yang unggul dan berdaya saing dalam menghasilkan insinyur profesional yang berintegritas, beretika, dan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan profesi keinsinyuran yang bermutu sesuai standar UU Keinsinyuran dan PII.\n2. Mengembangkan praktik keinsinyuran dan penelitian terapan yang menjamin keselamatan, kesehatan, serta kelestarian lingkungan.\n3. Melaksanakan pengabdian kepada masyarakat melalui penerapan keinsinyuran profesional dan etika profesi.','Jalur RPL (1 Semester / Portofolio Pengalaman >= 2 Tahun) & Jalur Reguler (2 Semester): Kode Etik & Etika Profesi Insinyur, Profesionalisme Keinsinyuran, K3L (Kesehatan dan Keselamatan Lingkungan), Praktik Keinsinyuran Industri/Proyek (Total 24 SKS)','Insinyur Profesional Bersertifikat (STRI / PII), Penanggung Jawab Teknis Proyek Konstruksi & Industri, Konsultan Teknik Senior, Pengajuan Jenjang Insinyur Profesional Pratama / Madya / Utama','Seleksi Mandiri melalui laman PSPPI FATEK UNTAD dan portal RPL UNTAD.',NULL,NULL),(77,8,'Fisika','S1','Unggul','S.Si.','Rp 3.000.000','Program studi di bawah Fakultas Matematika dan Ilmu Pengetahuan Alam (FMIPA) UNTAD yang berfokus pada penguasaan konsep fisika fundamental dan terapan (meliputi fisika material, instrumentasi & elektronika, fisika medis, serta fisika komputasi) berwawasan lingkungan Wallacea.','VISI KEILMUAN:\n\"Menjadi program studi fisika yang unggul dan berdaya saing dalam pengembangan sains dan aplikasi fisika berwawasan lingkungan Wallacea.\"\n\nMISI:\n1. Menyelenggarakan pendidikan fisika yang bermutu berbasis teori, eksperimen laboratorium, dan komputasi.\n2. Mengembangkan penelitian inovatif di bidang fisika material, instrumentasi/elektronika, fisika medis, dan fisika komputasi.\n3. Melaksanakan pengabdian kepada masyarakat melalui penerapan teknologi tepat guna dan literasi sains.','Mekanika Klasik, Elektrodinamika, Termodinamika, Fisika Kuantum, Fisika Zat Padat & Material, Elektronika & Instrumentasi, Komputasi Fisika, Kerja Praktik, Skripsi','Peneliti Sains (BRIN), Fisikawan Medis Rumah Sakit, Quality Control & Analis Material (Manufaktur / Pertambangan), Teknisi Instrumentasi, Dosen','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(78,8,'Matematika','S1','Unggul','S.Mat.','Rp 3.000.000','Program studi di bawah FMIPA UNTAD yang mengkaji matematika murni (analisis dan aljabar) maupun matematika terapan (pemodelan matematika, riset operasi, komputasi, dan aktuaria) untuk pemecahan masalah sains dan industri.','VISI KEILMUAN:\n\"Menjadi program studi matematika yang unggul dan berdaya saing dalam pengembangan matematika murni dan terapan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan matematika yang bermutu untuk memperkuat kemampuan analisis logis, pemodelan, dan komputasi.\n2. Mengembangkan penelitian di bidang analisis, aljabar, pemodelan matematika, riset operasi, komputasi, dan aktuaria.\n3. Melaksanakan pengabdian kepada masyarakat melalui penerapan pemodelan dan literasi matematika.','Kalkulus Peubah Banyak, Aljabar Linear & Struktur Aljabar, Analisis Real & Kompleks, Persamaan Diferensial, Pemodelan Matematika, Riset Operasi, Pemrograman & Komputasi Matematika, Kerja Praktik, Skripsi','Aktuaris / Analis Risiko (Asuransi & Perbankan), Data Analyst, Perencana Logistik & Riset Operasi, Peneliti, Dosen','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(79,8,'Statistika','S1','Baik Sekali','S.Stat.','Rp 4.000.000','Program studi di bawah FMIPA UNTAD yang berfokus pada teori probabilitas, perancangan survei dan eksperimen, pemodelan statistik, ekonometrika, serta analisis data besar (big data) untuk pengambilan keputusan berbasis data.','VISI KEILMUAN:\n\"Menjadi program studi statistika yang unggul dan berdaya saing dalam statistika terapan dan analisis data berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan statistika yang bermutu berbasis metode statistik modern dan komputasi data.\n2. Mengembangkan penelitian di bidang pemodelan statistik, survei & eksperimen, ekonometrika, dan big data.\n3. Melaksanakan pengabdian kepada masyarakat melalui pendampingan pengolahan data dan riset berbasis bukti.','Teori Peluang, Statistika Matematika, Analisis Regresi, Rancangan Percobaan, Analisis Multivariat, Analisis Deret Waktu (Time Series), Komputasi Statistika (R/Python), Kerja Praktik, Skripsi','Statistisi Pemerintah (BPS), Data Analyst / Business Intelligence (Teknologi / Perbankan / Industri), Konsultan Survei & Riset Pasar','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(80,8,'Teknik Geofisika','S1','Baik Sekali','S.T.','Rp 4.500.000','Program studi di bawah FMIPA UNTAD yang mempelajari sifat fisik bumi bawah permukaan menggunakan metode geofisika (seismik, gravitasi, geomagnet, geolistrik) untuk eksplorasi sumber daya mineral/energi dan mitigasi bencana gempa bumi/tsunami di Sulawesi.','VISI KEILMUAN:\n\"Menjadi program studi teknik geofisika yang unggul dalam eksplorasi sumber daya alam dan mitigasi bencana kebumian berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan teknik geofisika yang bermutu dengan penguatan akuisisi, pengolahan, dan interpretasi data geofisika.\n2. Mengembangkan penelitian di bidang geofisika eksplorasi (mineral, panas bumi, migas) dan geofisika kebencanaan.\n3. Melaksanakan pengabdian kepada masyarakat dalam mitigasi bencana gempa/tsunami dan pemanfaatan sumber daya bumi.','Geologi Dasar, Seismologi & Geofisika Gempa Bumi, Metode Geolistrik & Elektromagnetik, Metode Gravitasi & Magnetik, Eksplorasi Panas Bumi & Mineral, Pengolahan Sinyal Geofisika, Kuliah Lapangan Geofisika, Skripsi','Geophysicist Eksplorasi (Pertambangan Nikel / Emas / Migas / Panas Bumi), Ahli Kebencanaan (BMKG / PVMBG / BPBD), Konsultan Geoteknik & Survei Bawah Permukaan','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(81,8,'Sains Data','S1','Baik','S.Si.D.','Rp 5.000.000','Program studi di bawah FMIPA UNTAD yang memadukan ilmu statistika, matematika komputasi, dan pemrograman kecerdasan buatan (machine learning) untuk mengolah dan mengekstraksi nilai strategis dari big data.','VISI KEILMUAN:\n\"Menjadi program studi sains data yang unggul dan adaptif dalam pengolahan big data dan kecerdasan buatan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan sains data yang bermutu berbasis statistika, komputasi, dan machine learning.\n2. Mengembangkan penelitian terapan di bidang data science, big data analytics, data mining, dan kecerdasan buatan.\n3. Melaksanakan pengabdian kepada masyarakat melalui pemanfaatan analitik data untuk solusi daerah dan industri.','Pemrograman Sains Data (Python/R/SQL), Struktur Data & Basis Data, Statistika Inferensial, Machine Learning & Deep Learning, Penambangan Data (Data Mining), Visualisasi Data, Big Data Analytics, Magang Industri, Skripsi','Data Scientist, Data Engineer, Machine Learning Engineer, Business Intelligence Analyst (Teknologi / Perbankan / Industri / Instansi Pemerintah)','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(82,8,'Biologi','S1','Unggul','S.Si.','Rp 3.000.000','Program studi di bawah FMIPA UNTAD yang berfokus pada kajian biodiversitas dan konservasi ekosistem endemik kawasan Wallacea (Sulawesi), bioteknologi, mikrobiologi, serta ekologi tropis.','VISI KEILMUAN:\n\"Menjadi program studi biologi yang unggul dan berdaya saing dalam konservasi keanekaragaman hayati Wallacea dan bioteknologi berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan biologi yang bermutu berbasis riset hayati, ekologi, mikrobiologi, dan bioteknologi.\n2. Mengembangkan penelitian unggulan di bidang biodiversitas Wallacea, konservasi, mikrobiologi, dan bioteknologi tropis.\n3. Melaksanakan pengabdian kepada masyarakat dalam pelestarian hayati, rehabilitasi lahan, dan bioteknologi terapan.','Biologi Sel & Molekuler, Struktur & Perkembangan Tumbuhan/Hewan, Mikrobiologi, Genetika, Ekologi & Konservasi Sumber Daya Hayati Wallacea, Bioteknologi, Kerja Praktik, Skripsi','Peneliti Hayati & Konservasi (BRIN / KLHK / Taman Nasional), Staf QC/QA Mikrobiologi (Pangan & Farmasi), Konsultan AMDAL & Rehabilitasi Lahan Tambang, Dosen','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(83,8,'Kimia','S1','Unggul','S.Si.','Rp 3.000.000','Program studi di bawah FMIPA UNTAD yang berfokus pada penguasaan ilmu kimia (organik, anorganik, analitik, fisik, dan biokimia) dengan keunggulan riset kimia bahan alam endemik Sulawesi dan analisis material/mineral.','VISI KEILMUAN:\n\"Menjadi program studi kimia yang unggul dan berdaya saing dalam kimia bahan alam dan analisis material/lingkungan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan kimia yang bermutu berbasis laboratorium, riset, dan keselamatan kerja kimia.\n2. Mengembangkan penelitian di bidang kimia organik/bahan alam, kimia analitik/material, kimia anorganik, fisik, dan biokimia.\n3. Melaksanakan pengabdian kepada masyarakat melalui pengujian kualitas, pengolahan bahan alam, dan pengelolaan limbah kimia.','Kimia Dasar, Kimia Analitik & Instrumentasi, Kimia Organik, Kimia Anorganik, Kimia Fisika, Biokimia, Kimia Bahan Alam, Praktikum Laboratorium Terpadu, Kerja Praktik, Skripsi','Analis Laboratorium Kimia & Quality Control (Pertambangan / Smelter Nikel / Pangan / Farmasi / Kosmetik), Peneliti (BRIN / BPOM), Konsultan Lingkungan, Dosen','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(84,8,'Farmasi','S1','Baik Sekali','S.Farm.','Rp 7.000.000','Program studi di bawah FMIPA UNTAD yang mempelajari ilmu kefarmasian mulai dari penemuan bahan obat alami, formulasi sediaan farmasi, farmakologi, hingga pelayanan farmasi klinis dan komunitas.','VISI KEILMUAN:\n\"Menjadi program studi farmasi yang unggul dan berdaya saing dalam pengembangan sediaan farmasi berbasis bahan alam dan pelayanan kefarmasian berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan kefarmasian yang bermutu berbasis standar profesi, riset bahan alam, dan farmasi klinis/komunitas.\n2. Mengembangkan penelitian di bidang farmakognosi/fitokimia, teknologi sediaan farmasi, farmakologi, dan kimia farmasi.\n3. Melaksanakan pengabdian kepada masyarakat melalui edukasi penggunaan obat rasional dan pelayanan kesehatan.','Farmasetika Dasar, Kimia Farmasi, Farmakognosi & Fitokimia, Farmakologi & Toksikologi, Teknologi Sediaan Solid/Liquid/Semisolid, Farmasi Klinis & Komunitas, Praktikum Laboratorium, Skripsi','Melanjutkan ke Profesi Apoteker (RS / Apotek / Industri Farmasi), Staf R&D / QC / QA Obat, Makanan & Kosmetik, Aparatur BPOM & Dinas Kesehatan','SNBP (Seleksi Nasional Berdasarkan Prestasi), SNBT (Seleksi Nasional Berdasarkan Tes), dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(85,8,'Pendidikan Profesi Apoteker','Profesi','Baik Sekali','apt.','Mandiri Profesi (Kisaran Rp 10.000.000 - Rp 12.500.000 / Semester)','Program studi profesi di bawah Jurusan Farmasi FMIPA UNTAD untuk mencetak apoteker profesional yang kompeten dalam pelayanan kefarmasian klinis/komunitas maupun produksi serta pengawasan sediaan farmasi berbasis bahan alam.','VISI KEILMUAN:\n\"Menjadi program studi pendidikan profesi apoteker yang unggul dan berdaya saing dalam pelayanan kefarmasian dan pengembangan obat berbasis bahan alam berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan profesi apoteker yang bermutu berbasis standar kompetensi profesi, etika, dan keselamatan pasien.\n2. Mengembangkan praktik kefarmasian dan riset terapan di bidang farmasi klinis/komunitas, teknologi sediaan, dan bahan alam.\n3. Melaksanakan pengabdian kepada masyarakat melalui pelayanan kefarmasian dan edukasi kesehatan.','Praktik Kerja Profesi Apoteker (PKPA) di Apotek, Rumah Sakit, Puskesmas, Industri Farmasi, dan Balai POM, serta Uji Kompetensi Mahasiswa Program Profesi Apoteker Indonesia (UKMPPAI) (36?38 SKS, 2 Semester)','Apoteker Penanggung Jawab (Apotek & Rumah Sakit), Apoteker Klinis, Apoteker Industri Farmasi / Kosmetik (Produksi, QC/QA, R&D), Aparatur BPOM & Dinas Kesehatan','Seleksi Mandiri khusus lulusan S1 Farmasi (CBT kefarmasian dan wawancara) yang dibuka oleh FMIPA UNTAD.',NULL,NULL),(86,8,'Magister Kimia','S2','Baik','M.Si.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi magister di bawah Jurusan Kimia FMIPA dan Pascasarjana UNTAD dengan fokus penelitian pada Kimia Bahan Alam (eksplorasi senyawa bioaktif endemik kawasan Wallacea), Kimia Analitik & Lingkungan, serta Kimia Material/Energi.','VISI KEILMUAN:\n\"Menjadi program studi magister kimia yang unggul dan berdaya saing dalam kimia bahan alam Wallacea, kimia analitik/lingkungan, dan kimia material berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister kimia yang bermutu berbasis riset dan metode analisis modern.\n2. Mengembangkan penelitian inovatif di bidang kimia organik bahan alam, kimia analitik/lingkungan, dan kimia material/energi.\n3. Melaksanakan pengabdian kepada masyarakat melalui diseminasi riset kimia, pengujian kualitas, dan pengelolaan lingkungan.','Filsafat Ilmu & Metodologi Penelitian Kimia, Kimia Organik Bahan Alam Lanjut, Kimia Analitik & Elusidasi Struktur Molekul, Kimia Lingkungan & Material Lanjut, Publikasi Karya Ilmiah, Seminar, Tesis','Dosen Ilmu Kimia, Peneliti Senior (BRIN / BPOM / Laboratorium Daerah), Manajer Laboratorium & R&D (Pertambangan / Pengolahan Mineral / Farmasi), Konsultan Analisis Lingkungan','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL),(87,6,'Kehutanan','S1','Baik Sekali','S.Hut.','Rp 1.750.000','Program studi di bawah Fakultas Kehutanan (FAHUT) UNTAD di Sulawesi Tengah (kawasan Wallacea) dengan 4 bidang peminatan keahlian: Manajemen Sumber Daya Hutan, Konservasi Sumber Daya Hutan, Budidaya Hutan (Silvikultur), serta Teknologi Hasil Hutan.','VISI KEILMUAN:\n\"Menyelenggarakan kegiatan akademik untuk menghasilkan lulusan yang berkualitas dan berdaya saing internasional dalam mendukung pengelolaan sumber daya hutan secara berkelanjutan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan tinggi kehutanan berbasis OBE yang bermutu dan berdaya saing internasional.\n2. Mengembangkan penelitian di bidang manajemen hutan, konservasi biodiversitas Wallacea, silvikultur, dan teknologi hasil hutan berkelanjutan.\n3. Melaksanakan pengabdian kepada masyarakat melalui pengelolaan hutan lestari, perhutanan sosial, dan pelestarian lingkungan.','Pengantar Ilmu Kehutanan, Dendrologi, Ekologi Hutan, Silvikultur, Inventarisasi & Pemetaan Hutan (SIG Kehutanan), Perlindungan & Pengamanan Hutan, Konservasi Biodiversitas Wallacea, Teknologi Pengolahan Hasil Hutan Kayu & Non-Kayu, Praktik Umum Kehutanan Terpadu di Hutan Pendidikan, KKN, Skripsi','Polisi Kehutanan (Polhut) & Penyuluh Kehutanan (ASN), Pengelola Kawasan Konservasi (Taman Nasional / BKSDA), Manajer HTI & Perhutanan Sosial, Spesialis Reklamasi Hutan & Lingkungan Pertambangan, Konsultan Kehutanan & Karbon Hutan','SNBP, SNBT, SMMPTN / Seleksi Mandiri UNTAD, dan jalur Rekognisi Pembelajaran Lampau (RPL).',NULL,NULL),(88,4,'Keperawatan','D3','Baik','A.Md.Kep.','Rp 2.000.000','Program studi vokasi kesehatan di bawah Fakultas Kedokteran (FK) UNTAD (Kampus Tondo, Palu) dengan keunggulan kekhususan pada pelayanan keperawatan gawat darurat dan bencana berlandaskan nilai-nilai profesionalisme.','VISI KEILMUAN:\n\"Menjadi Program Studi D-III Keperawatan yang unggul dalam pelayanan keperawatan gawat darurat dan bencana berlandaskan nilai-nilai profesionalisme.\"\n\nMISI:\n1. Menyelenggarakan pendidikan vokasi keperawatan yang bermutu dengan keunggulan keperawatan gawat darurat dan bencana.\n2. Mengembangkan penelitian terapan di bidang keperawatan gawat darurat, kebencanaan, dan pelayanan klinik.\n3. Melaksanakan pengabdian kepada masyarakat melalui edukasi kesehatan dan penanggulangan kegawatdaruratan/bencana.','Ilmu Biomedik Dasar, Keperawatan Dasar, Keperawatan Medikal Bedah, Keperawatan Anak & Maternitas, Keperawatan Jiwa & Gerontik, Keperawatan Gawat Darurat & Manajemen Bencana, Praktik Klinik Keperawatan (RS/Puskesmas), Karya Tulis Ilmiah (KTI), Uji Kompetensi Nasional Perawat (UKOM)','Perawat Pelaksana (Rumah Sakit / Puskesmas / Klinik), Perawat Tim Tanggap Darurat & Bencana (BPBD / BASARNAS / PMI), Perawat Industri & Pertambangan (K3 Kesehatan), Tenaga Kesehatan Luar Negeri','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD (dengan syarat surat keterangan sehat dan tidak buta warna).',NULL,NULL),(89,4,'Kedokteran','S1','Baik Sekali','S.Ked.','Rp 20.000.000 (IPI Mandiri Rp 300.000.000)','Program studi sarjana kedokteran di bawah Fakultas Kedokteran (FK) UNTAD (berdiri sejak 2008 di Kampus Bumi Tadulako, Palu) dengan keunggulan keilmuan lokal di bidang kedokteran kelautan/pesisir, penyakit tropis, dan traumatologi/kebencanaan.','VISI KEILMUAN:\n\"Menjadi program studi kedokteran yang unggul dan berdaya saing dalam pelayanan kesehatan, pendidikan, dan penelitian kedokteran pesisir, penyakit tropis, serta kebencanaan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan kedokteran berbasis OBE dan kurikulum blok terintegrasi (PBL, praktikum biomedik, dan CSL) yang bermutu.\n2. Mengembangkan penelitian di bidang kedokteran pesisir/kelautan, penyakit tropis, traumatologi/kebencanaan, dan kesehatan masyarakat.\n3. Melaksanakan pengabdian kepada masyarakat melalui pelayanan promotif, preventif, kuratif, dan rehabilitatif serta penanggulangan kedaruratan/bencana.','Kurikulum 2025 Berbasis OBE (160 SKS, 7?8 Semester, Sistem Blok Terintegrasi, PBL, Praktikum Biomedik & CSL): Anatomi, Histologi, Fisiologi, Biokimia, Mikrobiologi, Parasitologi, Farmakologi, Patologi Klinik & Anatomi, Blok Sistem Organ, Kedokteran Pesisir & Kebencanaan, Skripsi','Melanjutkan wajib ke Program Pendidikan Profesi Dokter (Koas / dr.), Peneliti Biomedis & Kesehatan Masyarakat, Staf Medis Perusahaan, Dosen Ilmu Kedokteran Dasar','SNBP, SNBT (bebas IPI), dan SMMPTN / Seleksi Mandiri UNTAD (IPI Rp 300.000.000; syarat sehat fisik/jiwa, bebas narkoba, tidak buta warna).',NULL,NULL),(90,4,'Profesi Dokter','Profesi','Baik Sekali','dr.','Sesuai UKT S1 Kedokteran / Ketetapan Tahap Profesi','Tahap pendidikan klinik (kepaniteraan klinik / Co-Ass) di bawah Fakultas Kedokteran (FK) UNTAD yang berorientasi pada pelayanan medis profesional, beretika, dan unggul dalam penanganan kasus penyakit tropis, kedokteran pesisir, serta traumatologi/kebencanaan.','VISI KEILMUAN:\n\"Menjadi program studi profesi dokter yang unggul dalam pelayanan medis, pendidikan klinik, dan penanggulangan masalah kesehatan pesisir, penyakit tropis, serta kebencanaan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan profesi dokter berbasis kompetensi klinik dan etika profesi di rumah sakit pendidikan dan jejaring.\n2. Mengembangkan praktik klinik dan riset aplikatif di bidang kedokteran pesisir, penyakit tropis, dan traumatologi/kebencanaan.\n3. Melaksanakan pengabdian kepada masyarakat melalui pelayanan kesehatan paripurna, promotif, preventif, kuratif, dan rehabilitatif.','Rotasi Stase Klinik (3?4 Semester / ~1,5?2 Tahun di RSUD Undata Palu, RSU Tadulako, RS Jejaring & Puskesmas): Ilmu Penyakit Dalam, Ilmu Bedah, Obstetri & Ginekologi, Ilmu Kesehatan Anak, Neurologi, Psikiatri, Kulit & Kelamin, Mata, THT-KL, Radiologi, Anestesiologi & Terapi Intensif, Kedokteran Forensik, Ilmu Kesehatan Masyarakat, serta UKMPPD (CBT & OSCE)','Dokter Umum (RS / Puskesmas / Klinik setelah Internship & STR), Dokter Perusahaan / Industri, Tenaga Medis Kemanusiaan, Melanjutkan PPDS (Dokter Spesialis)','Kelanjutan berjenjang khusus bagi lulusan S1 Kedokteran (S.Ked.) UNTAD yang telah menyelesaikan tahap sarjana akademik dan yudisium.',NULL,NULL),(91,10,'Peternakan','S1','Unggul','S.Pt.','Rp 3.000.000','Program studi perintis di Fakultas Peternakan dan Perikanan (FAPETKAN) UNTAD yang berfokus pada ilmu produksi ternak (ruminansia besar/kecil, unggas, dan aneka ternak lokal), nutrisi dan teknologi pakan, pemuliaan dan reproduksi ternak, serta teknologi pengolahan hasil ternak.','VISI KEILMUAN:\n\"Menghasilkan sarjana peternakan yang unggul, mandiri, dan berdaya saing dalam pengembangan IPTEKS peternakan berkelanjutan yang berwawasan lingkungan hidup di kawasan Timur Indonesia.\"\n\nMISI:\n1. Menyelenggarakan pendidikan tinggi peternakan yang bermutu, adaptif, dan berwawasan lingkungan.\n2. Mengembangkan penelitian di bidang produksi, nutrisi/pakan, pemuliaan/reproduksi, dan pengolahan hasil ternak berkelanjutan.\n3. Melaksanakan pengabdian kepada masyarakat melalui penerapan teknologi peternakan dan pemberdayaan peternak.','Ilmu Nutrisi & Makanan Ternak, Ilmu Produksi Ternak Potong/Perah/Unggas, Ilmu Pemuliaan & Reproduksi Ternak, Teknologi Pengolahan Hasil Ternak, Manajemen Agribisnis Peternakan, Magang/KKN, Skripsi','Manajer / Supervisor Peternakan (Poultry & Feedlot), Formulator Pakan Ternak, Penyuluh Peternakan (ASN Dinas Peternakan/Pertanian), Petugas Karantina Hewan, Wirausahawan Peternakan','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(92,10,'Akuakultur','S1','Baik Sekali','S.Pi.','Rp 3.000.000','Program studi di bawah FAPETKAN UNTAD (dahulu bernama Budidaya Perairan) yang berfokus pada rekayasa teknologi budidaya organisme akuatik air tawar, payau, dan laut (ikan, udang vaname, rumput laut, dan kerang mutiara) secara berkelanjutan berbasis potensi perikanan Sulawesi Tengah.','VISI KEILMUAN:\n\"Menjadi pusat pengembangan ilmu dan teknologi budidaya perairan yang unggul dan inovatif dalam mendukung ketahanan pangan dan ekonomi kelautan-perikanan berkelanjutan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan akuakultur yang bermutu berbasis praktik budidaya dan inovasi teknologi.\n2. Mengembangkan penelitian di bidang pembenihan, pembesaran, manajemen kualitas air, pakan, dan kesehatan organisme akuatik.\n3. Melaksanakan pengabdian kepada masyarakat melalui transfer teknologi budidaya perairan yang ramah lingkungan.','Dasar-Dasar Akuakultur, Biologi Perikanan, Manajemen Kualitas Air, Nutrisi & Teknologi Pakan Ikan, Pembenihan & Pembesaran Organisme Akuatik, Penyakit & Kesehatan Ikan, Desain & Tata Letak Tambak/Kolam, Praktik Kerja Lapangan, Skripsi','Manajer / Teknisi Tambak Udang & Budidaya Perikanan, Penyuluh Perikanan (ASN KKP / Dinas Perikanan), Petugas Karantina Ikan, Wirausahawan Budidaya Perikanan','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(93,10,'Sumber Daya Akuatik','S1','Baik','S.Pi.','Rp 3.000.000','Program studi di bawah FAPETKAN UNTAD yang mengkaji pengelolaan berkelanjutan sumber daya perairan tawar (danau, sungai) dan pesisir (seperti Danau Poso, Danau Lindu, dan Teluk Palu), dinamika populasi ikan, ekotoksikologi perairan, serta konservasi ekosistem akuatik.','VISI KEILMUAN:\n\"Mengembangkan ilmu manajemen sumber daya perairan yang unggul dalam pelestarian biodiversitas akuatik dan pemanfaatan stok perikanan secara lestari.\"\n\nMISI:\n1. Menyelenggarakan pendidikan pengelolaan sumber daya akuatik yang bermutu berbasis riset ekologi dan perikanan.\n2. Mengembangkan penelitian di bidang limnologi/oseanografi, dinamika populasi ikan, ekotoksikologi, dan konservasi perairan.\n3. Melaksanakan pengabdian kepada masyarakat dalam pengelolaan perairan dan konservasi ekosistem akuatik berkelanjutan.','Ikhtiologi, Limnologi & Oseanografi Dasar, Dinamika Populasi Ikan, Ekologi Perairan, Manajemen Sumber Daya Perikanan Tangkap, Pencemaran & Konservasi Perairan, Praktik Lapangan, Skripsi','Analis Pengelolaan Sumber Daya Perairan (KKP / Dinas Perikanan), Konsultan Lingkungan Perairan (AMDAL Pesisir/Tambang), Peneliti Perikanan, Pengelola Kawasan Konservasi Perairan','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(94,10,'Sosial Ekonomi Peternakan','S1','Baik','S.Pt.','Rp 3.000.000','Program studi di bawah FAPETKAN UNTAD yang memadukan ilmu teknis peternakan dengan manajemen agribisnis, pemasaran produk peternakan, analisis usaha ternak, penyuluhan, serta pemberdayaan ekonomi peternak rakyat.','VISI KEILMUAN:\n\"Menghasilkan sarjana sosial ekonomi peternakan yang inovatif, berjiwa wirausaha, dan mampu mendorong kemandirian ekonomi peternak berbasis kearifan lokal.\"\n\nMISI:\n1. Menyelenggarakan pendidikan sosial ekonomi peternakan yang bermutu berbasis agribisnis dan kewirausahaan.\n2. Mengembangkan penelitian di bidang ekonomi produksi, rantai nilai/pemasaran ternak, penyuluhan, dan pemberdayaan peternak.\n3. Melaksanakan pengabdian kepada masyarakat melalui pendampingan usaha peternakan dan penguatan ekonomi lokal.','Pengantar Ilmu Peternakan, Ekonomi Produksi Peternakan, Manajemen Agribisnis Peternakan, Pemasaran & Rantai Nilai Produk Ternak, Penyuluhan & Komunikasi Pembangunan Peternakan, Studi Kelayakan Usaha Peternakan, Magang/KKN, Skripsi','Manajer / Analis Bisnis (Industri Perunggasan / Pakan / Pengolahan Produk Ternak), Konsultan Agribisnis Peternakan, Aparatur Dinas Peternakan / Ketahanan Pangan, Wirausahawan Peternakan','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(95,10,'Ilmu Kelautan','S1','Baik','S.Kel.','Rp 3.000.000','Program studi di bawah FAPETKAN UNTAD yang mengkaji oseanografi fisik/kimia/biologi, ekosistem terumbu karang, padang lamun, dan mangrove, pemetaan pesisir/laut (SIG kelautan), serta eksplorasi bioteknologi kelautan di perairan Sulawesi Tengah.','VISI KEILMUAN:\n\"Menjadi program studi unggul dalam pengembangan ilmu dan teknologi kelautan tropis untuk konservasi dan pemanfaatan sumber daya laut berkelanjutan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan ilmu kelautan yang bermutu berbasis oseanografi, ekologi pesisir/laut, dan teknologi geospasial kelautan.\n2. Mengembangkan penelitian di bidang ekosistem laut tropis, oseanografi, konservasi laut, dan mitigasi bencana pesisir.\n3. Melaksanakan pengabdian kepada masyarakat dalam konservasi laut, ekowisata bahari, dan pengelolaan wilayah pesisir.','Oseanografi Fisika/Kimia/Biologi, Ekologi Laut Tropis (Terumbu Karang, Mangrove, Lamun), Selam Ilmiah (Scientific Diving), Penginderaan Jauh & SIG Kelautan, Konservasi Sumber Daya Laut, Mitigasi Bencana Pesisir, Praktik Lapangan Kelautan, Skripsi','Peneliti Kelautan & Oseanografi (BRIN / KKP), Pengelola Kawasan Konservasi Laut (KKP / Taman Nasional Kepulauan Togean), Konsultan Survei Hidrografi & AMDAL Pesisir/Pelabuhan, Spesialis Ekowisata Bahari','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(96,7,'Kesehatan Masyarakat','S1','Baik Sekali','S.K.M.','Rp 5.000.000','Program studi di bawah Fakultas Kesehatan Masyarakat (FKM) UNTAD (berdiri sejak 2008 dan menjadi fakultas mandiri pada 2017) yang memiliki 7 departemen peminatan (termasuk Epidemiologi, AKK, PKIP, K3, dan Kesling) dengan visi berwawasan bencana.','VISI KEILMUAN:\n\"Menjadi program studi kesehatan masyarakat yang unggul dan berdaya saing dalam pengembangan ilmu dan praktik kesehatan masyarakat berwawasan bencana dan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan kesehatan masyarakat berbasis OBE yang bermutu dan berwawasan kebencanaan.\n2. Mengembangkan penelitian di bidang epidemiologi, administrasi kebijakan kesehatan, promosi kesehatan, K3, dan kesehatan lingkungan.\n3. Melaksanakan pengabdian kepada masyarakat melalui pemberdayaan, promotif-preventif, dan penanggulangan masalah kesehatan.','Kurikulum OBE (144 SKS, 7?8 Semester, 7 Departemen Peminatan termasuk Epidemiologi, AKK, PKIP, K3, dan Kesehatan Lingkungan), Praktik Belajar Lapangan (PBL), Magang/PKL, Skripsi','Tenaga Kesehatan Masyarakat (Puskesmas / Rumah Sakit / Dinas Kesehatan), HSE Officer, Peneliti Kesehatan Masyarakat, Konsultan Kesehatan & K3','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(97,7,'Gizi','S1','Unggul','S.Gz.','Rp 7.000.000','Program studi di bawah FKM UNTAD yang berfokus pada gizi klinis, gizi masyarakat, manajemen penyelenggaraan makanan, serta gizi kebencanaan.','VISI KEILMUAN:\n\"Menjadi program studi gizi yang unggul dan berdaya saing dalam pelayanan gizi klinis, masyarakat, penyelenggaraan makanan, dan gizi kebencanaan berwawasan lingkungan.\"\n\nMISI:\n1. Menyelenggarakan pendidikan gizi yang bermutu berbasis standar kompetensi profesi, riset, dan kebutuhan kebencanaan.\n2. Mengembangkan penelitian di bidang gizi klinis, gizi masyarakat, penyelenggaraan makanan, dan gizi darurat/bencana.\n3. Melaksanakan pengabdian kepada masyarakat melalui perbaikan status gizi dan edukasi pangan sehat.','Kurikulum Gizi (144?146 SKS, 8 Semester): Gizi Dasar & Biomedik, Dietetika & Gizi Klinis, Gizi Masyarakat, Manajemen Sistem Penyelenggaraan Makanan (MSPM), Gizi Kebencanaan, Praktik Kerja Lapangan (PKL), Skripsi','Nutrisionis / Dietisien Rumah Sakit & Klinik, Konsultan Gizi, Manajemen Industri Pangan & Penyelenggaraan Makanan, Tenaga Gizi Puskesmas / Instansi Kesehatan','SNBP, SNBT, dan SMMPTN / Seleksi Mandiri UNTAD.',NULL,NULL),(98,7,'Magister Kesehatan Masyarakat','S2','Baik','M.K.M.','Rp 7.000.000 (Matrikulasi Rp 750.000)','Program studi magister di bawah FKM dan Pascasarjana UNTAD yang menawarkan konsentrasi seperti AKK, Epidemiologi, Promosi Kesehatan, serta Kesehatan Lingkungan/K3.','VISI KEILMUAN:\n\"Menjadi program studi magister kesehatan masyarakat yang unggul dan berdaya saing dalam kebijakan kesehatan, epidemiologi, promosi kesehatan, dan K3/kesling berwawasan bencana.\"\n\nMISI:\n1. Menyelenggarakan pendidikan magister kesehatan masyarakat yang bermutu dan berbasis riset.\n2. Mengembangkan penelitian di bidang AKK, epidemiologi, promosi kesehatan, dan kesehatan lingkungan/K3.\n3. Melaksanakan pengabdian kepada masyarakat melalui advokasi kebijakan dan penguatan sistem kesehatan.','Filsafat Ilmu & Metodologi Penelitian Kesehatan Masyarakat, Biostatistika Lanjut, Mata Kuliah Konsentrasi (AKK / Epidemiologi / Promosi Kesehatan / Kesehatan Lingkungan & K3), Publikasi Karya Ilmiah, Seminar, Tesis (36?42 SKS)','Dosen Kesehatan Masyarakat, Analis Kebijakan Kesehatan, Manajer Fasilitas & Program Kesehatan, Peneliti Kesehatan Masyarakat','Seleksi Mandiri Pascasarjana UNTAD melalui portal PMB UNTAD.',NULL,NULL);
