INSERT INTO `profil_kampus` VALUES (1,'Universitas Tadulako','Universitas Tadulako (UNTAD) adalah perguruan tinggi negeri unggulan di Kota Palu, Sulawesi Tengah, yang berfokus pada penyelenggaraan pendidikan tinggi terintegrasi dengan pengembangan ilmu pengetahuan dan teknologi (IPTEKS) berwawasan lingkungan hidup. Berdiri resmi secara mandiri sejak 14 Agustus 1981 berdasarkan Keppres No. 36 Tahun 1981, universitas terbesar di Sulawesi Tengah ini membekali puluhan ribu mahasiswanya dengan kapasitas akademik yang kuat, pemanfaatan teknologi informasi terpadu, serta penanaman karakter kepemimpinan luhur (Tadulako) untuk menghasilkan lulusan yang kompetitif, inovatif, dan berdampak nyata bagi pembangunan daerah maupun nasional.','Untad/Untad.png');
